3365	// === ai.js — Racing Game ===
3366	// AI opponent cars with path-following behavior, personality, and rendering.
3367	// Attaches to window.R. Assumes R.canvas, R.ctx, R.CONFIG, R.track, R.camera,
3368	// R.state, R.input already exist.
3369	
3370	(function() {
3371	  'use strict';
3372	  var R = window.R;
3373	
3374	  /* ==========================================================================
3375	     Constants — all tunable AI values
3376	     ========================================================================== */
3377	
3378	  /** Default AI config values (merged into R.CONFIG if not already set) */
3379	  const AI_DEFAULTS = {
3380	    AI_COUNT: 7,
3381	    AI_DRIVER_NAMES: [
3382	      'T.Kobayashi', 'M.Sato', 'H.Tanaka', 'R.Yamamoto',
3383	      'S.Nakamura', 'K.Takahashi', 'A.Watanabe', 'J.Ito',
3384	      'Y.Suzuki', 'D.Fujita', 'B.Shimizu', 'C.Mori',
3385	      'E.Kimura', 'F.Inoue', 'G.Aoki', 'I.Yoshida'
3386	    ],
3387	    AI_COLORS: [
3388	      '#e63946', '#457b9d', '#2a9d8f', '#e9c46a',
3389	      '#f4a261', '#264653', '#d4a373', '#bc6c25',
3390	      '#7209b7', '#f72585', '#4cc9f0', '#4361ee'
3391	    ],
3392	    AI_AGGRESSION_RANGE: [0.2, 0.9],
3393	    AI_SKILL_MIN: 0.4,
3394	    AI_SKILL_MAX: 0.95,
3395	    AI_LOOKAHEAD_BASE: 280,
3396	    AI_LOOKAHEAD_SPEED_FACTOR: 2.5,
3397	    AI_STEER_SMOOTH: 0.08,
3398	    AI_STEER_SMOOTH_HIGH_SKILL: 0.14,
3399	    AI_BRAKE_CURVATURE_THRESHOLD: 0.008,
3400	    AI_BRAKE_HARD_CURVATURE: 0.025,
3401	    AI_OVERTAKE_RANGE: 220,
3402	    AI_DEFEND_RANGE: 200,
3403	    AI_OFFTRACK_THRESHOLD: 60,
3404	    AI_RUBBERBAND_FACTOR: 0.05,
3405	    AI_RUBBERBAND_RANGE: 600,
3406	    AI_STAGGER_DISTANCE: 120,
3407	    AI_NAME_TAG_OFFSET_Y: -42,
3408	    AI_BADGE_RADIUS: 8,
3409	    AI_MAX_SPEED_VARIANCE: 0.92,
3410	    AI_ACCELERATION_VARIANCE: 0.88
3411	  };
3412	
3413	  /* Merge defaults into R.CONFIG */
3414	  for (const key in AI_DEFAULTS) {
3415	    if (R.CONFIG[key] === undefined) {
3416	      R.CONFIG[key] = AI_DEFAULTS[key];
3417	    }
3418	  }
3419	
3420	  /* ==========================================================================
3421	     AI Car Array
3422	     ========================================================================== */
3423	
3424	  R.aiCars = [];
3425	
3426	  /* ==========================================================================
3427	     Internal utility helpers
3428	     ========================================================================== */
3429	
3430	  /**
3431	   * Clamp value between min and max.
3432	   * @param {number} v
3433	   * @param {number} lo
3434	   * @param {number} hi
3435	   * @returns {number}
3436	   */
3437	  function clamp(v, lo, hi) {
3438	    return v < lo ? lo : v > hi ? hi : v;
3439	  }
3440	
3441	  /**
3442	   * Linear interpolation.
3443	   * @param {number} a
3444	   * @param {number} b
3445	   * @param {number} t
3446	   * @returns {number}
3447	   */
3448	  function lerp(a, b, t) {
3449	    return a + (b - a) * t;
3450	  }
3451	
3452	  /**
3453	   * Random float in [min, max).
3454	   * @param {number} min
3455	   * @param {number} max
3456	   * @returns {number}
3457	   */
3458	  function randRange(min, max) {
3459	    return min + Math.random() * (max - min);
3460	  }
3461	
3462	  /**
3463	   * Random element from an array.
3464	   * @param {any[]} arr
3465	   * @returns {any}
3466	   */
3467	  function randChoice(arr) {
3468	    return arr[Math.floor(Math.random() * arr.length)];
3469	  }
3470	
3471	  /**
3472	   * Normalize an angle to [-PI, PI].
3473	   * @param {number} a
3474	   * @returns {number}
3475	   */
3476	  function normalizeAngle(a) {
3477	    while (a > Math.PI) a -= Math.PI * 2;
3478	    while (a < -Math.PI) a += Math.PI * 2;
3479	    return a;
3480	  }
3481	
3482	  /**
3483	   * Calculate shortest signed angle difference from current to target.
3484	   * @param {number} current
3485	   * @param {number} target
3486	   * @returns {number} delta in [-PI, PI]
3487	   */
3488	  function angleDelta(current, target) {
3489	    return normalizeAngle(target - current);
3490	  }
3491	
3492	  /**
3493	   * Distance between two world points (xz plane — racing plane).
3494	   * @param {number} x1
3495	   * @param {number} z1
3496	   * @param {number} x2
3497	   * @param {number} z2
3498	   * @returns {number}
3499	   */
3500	  function dist2D(x1, z1, x2, z2) {
3501	    const dx = x1 - x2;
3502	    const dz = z1 - z2;
3503	    return Math.sqrt(dx * dx + dz * dz);
3504	  }
3505	
3506	  /* ==========================================================================
3507	     Track navigation helpers
3508	     ========================================================================== */
3509	
3510	  /**
3511	   * Get the track segment at a given worldZ position.
3512	   * Segments are assumed to be ordered by worldZ (increasing).
3513	   * @param {number} worldZ
3514	   * @returns {{ segment: object, index: number }|null}
3515	   */
3516	  function getSegmentAtZ(worldZ) {
3517	    const segs = R.track.segments;
3518	    if (!segs || segs.length === 0) return null;
3519	    /* Binary-ish search for the segment containing this z */
3520	    /**
3521	     * Track segments define the road ahead. We find the segment whose
3522	     * cumulative z range contains worldZ. Assumes segments are sequential.
3523	     */
3524	    let cumulativeZ = 0;
3525	    for (let i = 0; i < segs.length; i++) {
3526	      const seg = segs[i];
3527	      const segLength = seg.length || 200; // default segment length
3528	      if (worldZ >= cumulativeZ && worldZ < cumulativeZ + segLength) {
3529	        return { segment: seg, index: i, localZ: worldZ - cumulativeZ, segStartZ: cumulativeZ };
3530	      }
3531	      cumulativeZ += segLength;
3532	    }
3533	    /* Wrap around for looping track */
3534	    if (segs.length > 0) {
3535	      cumulativeZ = 0;
3536	      for (let i = 0; i < segs.length; i++) {
3537	        const seg = segs[i];
3538	        const segLength = seg.length || 200;
3539	        cumulativeZ += segLength;
3540	      }
3541	      const wrappedZ = ((worldZ % cumulativeZ) + cumulativeZ) % cumulativeZ;
3542	      let cz = 0;
3543	      for (let i = 0; i < segs.length; i++) {
3544	        const seg = segs[i];
3545	        const segLength = seg.length || 200;
3546	        if (wrappedZ >= cz && wrappedZ < cz + segLength) {
3547	          return { segment: seg, index: i, localZ: wrappedZ - cz, segStartZ: cz };
3548	        }
3549	        cz += segLength;
3550	      }
3551	    }
3552	    return null;
3553	  }
3554	
3555	  /**
3556	   * Calculate the cumulative distance traveled (z) by following the track.
3557	   * For AI position sorting, we use worldZ as the primary sort key.
3558	   * Accounts for lap count.
3559	   * @param {object} car
3560	   * @returns {number} total distance traveled
3561	   */
3562	  function getTotalDistance(car) {
3563	    const segs = R.track.segments;
3564	    if (!segs || segs.length === 0) return car.z || car.y || 0;
3565	    let trackLength = 0;
3566	    for (let i = 0; i < segs.length; i++) {
3567	      trackLength += segs[i].length || 200;
3568	    }
3569	    return (car.lap || 0) * trackLength + (car.z || car.y || 0);
3570	  }
3571	
3572	  /**
3573	   * Get the worldX center of the track at a given position.
3574	   * Accounts for curvature to offset the center line.
3575	   * @param {number} worldZ
3576	   * @param {number} lookaheadZ — how far ahead to look
3577	   * @returns {{ x: number, curvature: number }}
3578	   */
3579	  function getTrackCenterAt(worldZ, lookaheadZ) {
3580	    const zTarget = worldZ + lookaheadZ;
3581	    const segInfo = getSegmentAtZ(zTarget);
3582	    if (!segInfo) {
3583	      return { x: 400, curvature: 0 }; // default center
3584	    }
3585	    const seg = segInfo.segment;
3586	    /* Accumulate lateral offset from curvature of preceding segments */
3587	    let totalCurveOffset = 0;
3588	    let totalCurvature = 0;
3589	    const segs = R.track.segments;
3590	    let cz = 0;
3591	    for (let i = 0; i < segs.length && cz < zTarget; i++) {
3592	      const s = segs[i];
3593	      const sLen = s.length || 200;
3594	      if (cz < worldZ) {
3595	        cz += sLen;
3596	        continue;
3597	      }
3598	      const endZ = cz + sLen;
3599	      const overlapStart = Math.max(cz, worldZ);
3600	      const overlapEnd = Math.min(endZ, zTarget);
3601	      if (overlapEnd > overlapStart) {
3602	        const frac = (overlapEnd - overlapStart) / (zTarget - worldZ);
3603	        totalCurveOffset += (s.curvature || 0) * frac * sLen;
3604	        totalCurvature += (s.curvature || 0) * frac;
3605	      }
3606	      cz += sLen;
3607	      if (cz >= zTarget) break;
3608	    }
3609	    /* Segments have worldX — use the current segment's worldX plus curvature offset */
3610	    const segX = seg.worldX !== undefined ? seg.worldX : 400;
3611	    return { x: segX + totalCurveOffset * 0.5, curvature: totalCurvature };
3612	  }
3613	
3614	  /**
3615	   * Get the weighted average curvature of upcoming segments.
3616	   * Used for pre-braking decisions.
3617	   * @param {number} worldZ — current z position
3618	   * @param {number} lookDistance — how far ahead to scan
3619	   * @returns {number} average absolute curvature (0 = straight, >0 = curve)
3620	   */
3621	  function getUpcomingCurvature(worldZ, lookDistance) {
3622	    const segs = R.track.segments;
3623	    if (!segs || segs.length === 0) return 0;
3624	    let totalWeight = 0;
3625	    let weightedCurv = 0;
3626	    let cz = 0;
3627	    const endZ = worldZ + lookDistance;
3628	    for (let i = 0; i < segs.length; i++) {
3629	      const s = segs[i];
3630	      const sLen = s.length || 200;
3631	      const segEnd = cz + sLen;
3632	      if (segEnd > worldZ && cz < endZ) {
3633	        const overlapStart = Math.max(cz, worldZ);
3634	        const overlapEnd = Math.min(segEnd, endZ);
3635	        if (overlapEnd > overlapStart) {
3636	          /* Closer segments weighted more heavily */
3637	          const dist = overlapStart - worldZ;
3638	          const weight = (lookDistance - dist) / lookDistance * (overlapEnd - overlapStart);
3639	          weightedCurv += Math.abs(s.curvature || 0) * weight;
3640	          totalWeight += weight;
3641	        }
3642	      }
3643	      cz += sLen;
3644	      if (cz >= endZ) break;
3645	    }
3646	    return totalWeight > 0 ? weightedCurv / totalWeight : 0;
3647	  }
3648	
3649	  /**
3650	   * Calculate total track length (one lap).
3651	   * @returns {number}
3652	   */
3653	  function trackLength() {
3654	    const segs = R.track.segments;
3655	    if (!segs || segs.length === 0) return 10000;
3656	    let len = 0;
3657	    for (let i = 0; i < segs.length; i++) {
3658	      len += segs[i].length || 200;
3659	    }
3660	    return len;
3661	  }
3662	
3663	  /* ==========================================================================
3664	     R.initAI() — Create AI opponent cars
3665	     ========================================================================== */
3666	
3667	  /**
3668	   * Initialize all AI cars. Creates R.CONFIG.AI_COUNT cars with random
3669	   * driver names, colors, aggression, and skill levels.
3670	   * Positions AI cars at staggered z-distances behind the player.
3671	   */
3672	  R.initAI = function() {
3673	    R.aiCars = [];
3674	    const count = R.CONFIG.AI_COUNT || 7;
3675	    const names = R.CONFIG.AI_DRIVER_NAMES;
3676	    const colors = R.CONFIG.AI_COLORS;
3677	    /* Shuffle names and colors for variety */
3678	    const shuffledNames = [...names].sort(function() { return Math.random() - 0.5; });
3679	    const shuffledColors = [...colors].sort(function() { return Math.random() - 0.5; });
3680	    const tLen = trackLength();
3681	    const aggRange = R.CONFIG.AI_AGGRESSION_RANGE || [0.2, 0.9];
3682	    const skillMin = R.CONFIG.AI_SKILL_MIN || 0.4;
3683	    const skillMax = R.CONFIG.AI_SKILL_MAX || 0.95;
3684	
3685	    for (let i = 0; i < count; i++) {
3686	      const skill = randRange(skillMin, skillMax);
3687	      /* Base car properties (same shape as player car) */
3688	      const car = {
3689	        /* World position */
3690	        x: R.CONFIG.TRACK_CENTER_X || 400,
3691	        y: 0,
3692	        z: -R.CONFIG.AI_STAGGER_DISTANCE * (i + 1),
3693	        angle: 0,
3694	        speed: 0,
3695	        steerAngle: 0,
3696	        driftFactor: 0,
3697	        /* Race state */
3698	        lap: 0,
3699	        checkpointIdx: 0,
3700	        finished: false,
3701	        /* Visual */
3702	        color: shuffledColors[i % shuffledColors.length],
3703	        /* Performance (tuned per-car) */
3704	        maxSpeed: (R.CONFIG.CAR_MAX_SPEED || 12) * lerp(R.CONFIG.AI_MAX_SPEED_VARIANCE, 1.0, skill),
3705	        acceleration: (R.CONFIG.CAR_ACCELERATION || 0.15) * lerp(R.CONFIG.AI_ACCELERATION_VARIANCE, 1.0, skill),
3706	        braking: (R.CONFIG.CAR_BRAKING || 0.3),
3707	        handling: (R.CONFIG.CAR_HANDLING || 0.04) * skill,
3708	        /* AI-specific fields */
3709	        driverName: shuffledNames[i % shuffledNames.length],
3710	        aggression: randRange(aggRange[0], aggRange[1]),
3711	        skillLevel: skill,
3712	        targetSpeed: 0,
3713	        state: 'racing',        // 'racing' | 'overtaking' | 'defending' | 'recovering'
3714	        stateTimer: 0,
3715	        prevSteer: 0,
3716	        brakeLevel: 0,
3717	        prevWorldZ: -R.CONFIG.AI_STAGGER_DISTANCE * (i + 1),
3718	        totalDistance: 0,
3719	        overtakeTarget: null,   // reference to car being overtaken
3720	        defendAgainst: null,    // reference to car defending against
3721	        recoveryTimer: 0,
3722	        /* Visual animation */
3723	        wheelRotation: 0,
3724	        bodyBob: 0,
3725	        bobPhase: Math.random() * Math.PI * 2
3726	      };
3727	
3728	      /* Car-specific tuning: slightly randomize handling feel */
3729	      car.maxSpeed += randRange(-0.3, 0.3);
3730	      car.acceleration += randRange(-0.02, 0.02);
3731	      car.handling = clamp(car.handling, 0.02, 0.1);
3732	
3733	      R.aiCars.push(car);
3734	    }
3735	
3736	    /* Position AI cars ahead or behind based on skill (faster in front) */
3737	    /* Sort by skill so faster cars start nearer the front */
3738	    R.aiCars.sort(function(a, b) { return b.skillLevel - a.skillLevel; });
3739	    const stagger = R.CONFIG.AI_STAGGER_DISTANCE;
3740	    for (let i = 0; i < R.aiCars.length; i++) {
3741	      R.aiCars[i].z = -(stagger * (i + 1));
3742	      R.aiCars[i].prevWorldZ = R.aiCars[i].z;
3743	    }
3744	  };
3745	
3746	  /* ==========================================================================
3747	     R.updateAI(dt) — Main AI update per frame
3748	     ========================================================================== */
3749	
3750	  /**
3751	   * Update all AI cars each frame.
3752	   * @param {number} dt — delta time in seconds
3753	   */
3754	  R.updateAI = function(dt) {
3755	    if (R.state.phase !== 'racing') { return; }
3756	    if (!R.aiCars || R.aiCars.length === 0) { return; }
3757	
3758	    const dtClamped = Math.min(dt, 0.05); // cap to prevent physics explosion
3759	    const allCars = getAllCars(); // player + AI for interaction
3760	
3761	    for (let i = 0; i < R.aiCars.length; i++) {
3762	      const ai = R.aiCars[i];
3763	      if (ai.finished) { continue; }
3764	
3765	      updateAISingle(ai, i, dtClamped, allCars);
3766	    }
3767	  };
3768	
3769	  /**
3770	   * Update a single AI car for one frame.
3771	   * @param {object} ai
3772	   * @param {number} index
3773	   * @param {number} dt
3774	   * @param {object[]} allCars
3775	   */
3776	  function updateAISingle(ai, index, dt, allCars) {
3777	    /* ---- Step 1: Find target position ahead on track ---- */
3778	    const lookaheadDist = R.CONFIG.AI_LOOKAHEAD_BASE
3779	      + ai.speed * R.CONFIG.AI_LOOKAHEAD_SPEED_FACTOR * ai.skillLevel;
3780	    const trackInfo = getTrackCenterAt(ai.z, lookaheadDist);
3781	    const upcomingCurv = getUpcomingCurvature(ai.z, lookaheadDist);
3782	
3783	    /* ---- Step 2: Calculate desired angle to target ---- */
3784	    const targetX = trackInfo.x;
3785	    const targetZ = ai.z + lookaheadDist;
3786	    const currentX = ai.x;
3787	    const dx = targetX - currentX;
3788	    const dz = targetZ - ai.z;
3789	
3790	    let desiredAngle = Math.atan2(dx, dz);
3791	
3792	    /* Racing line optimization: skilled drivers hug the inside of curves */
3793	    if (trackInfo.curvature !== 0 && ai.skillLevel > 0.55) {
3794	      const curveSign = trackInfo.curvature > 0 ? 1 : -1;
3795	      const lineOffset = curveSign * R.track.segments[0].width * 0.15 * ai.skillLevel;
3796	      desiredAngle = Math.atan2(dx + lineOffset, dz);
3797	    }
3798	
3799	    /* ---- Step 3: Steer toward desired angle ---- */
3800	    const angleErr = angleDelta(ai.angle, desiredAngle);
3801	    const steerSmooth = lerp(
3802	      R.CONFIG.AI_STEER_SMOOTH,
3803	      R.CONFIG.AI_STEER_SMOOTH_HIGH_SKILL,
3804	      ai.skillLevel
3805	    );
3806	
3807	    /* Aggressive AIs turn faster */
3808	    const aggressionSteerMul = 0.7 + ai.aggression * 0.6;
3809	    let targetSteer = clamp(angleErr * steerSmooth * 15 * aggressionSteerMul, -1, 1);
3810	
3811	    /* Smoother transition for high-skill drivers */
3812	    ai.steerAngle = lerp(ai.prevSteer, targetSteer, steerSmooth * 3);
3813	    ai.prevSteer = ai.steerAngle;
3814	
3815	    /* ---- Step 4: AI state transitions ---- */
3816	    updateAIState(ai, allCars, upcomingCurv);
3817	
3818	    /* ---- Step 5: Speed control based on state and upcoming road ---- */
3819	    updateAISpeed(ai, dt, upcomingCurv, trackInfo);
3820	
3821	    /* ---- Step 6: Apply physics (same as player car physics) ---- */
3822	    applyCarPhysics(ai, dt);
3823	
3824	    /* ---- Step 7: Lap and checkpoint detection ---- */
3825	    updateAILapProgress(ai);
3826	
3827	    /* ---- Step 8: Off-track recovery ---- */
3828	    handleOffTrack(ai, dt);
3829	  }
3830	
3831	  /* ==========================================================================
3832	     AI State Machine
3833	     ========================================================================== */
3834	
3835	  /**
3836	   * Determine and transition AI state.
3837	   * @param {object} ai
3838	   * @param {object[]} allCars
3839	   * @param {number} upcomingCurv
3840	   */
3841	  function updateAIState(ai, allCars, upcomingCurv) {
3842	    /* Check for car ahead within overtaking range */
3843	    const carAhead = findCarAhead(ai, allCars, R.CONFIG.AI_OVERTAKE_RANGE);
3844	
3845	    /* Check for car behind within defending range */
3846	    const carBehind = findCarBehind(ai, allCars, R.CONFIG.AI_DEFEND_RANGE);
3847	
3848	    /* Check if off track */
3849	    const segInfo = getSegmentAtZ(ai.z);
3850	    const offTrack = isOffTrack(ai, segInfo);
3851	
3852	    /* State transitions */
3853	    if (offTrack && ai.state !== 'recovering') {
3854	      ai.state = 'recovering';
3855	      ai.recoveryTimer = 60;
3856	    } else if (ai.state === 'recovering') {
3857	      ai.recoveryTimer--;
3858	      if (!offTrack && ai.recoveryTimer <= 0) {
3859	        ai.state = 'racing';
3860	      }
3861	    } else if (carAhead && ai.aggression > 0.35 && !offTrack) {
3862	      /* Only attempt overtaking if car ahead is slower */
3863	      if (carAhead.speed < ai.speed * 1.05 || ai.aggression > 0.65) {
3864	        ai.state = 'overtaking';
3865	        ai.overtakeTarget = carAhead;
3866	      } else {
3867	        ai.state = 'racing';
3868	        ai.overtakeTarget = null;
3869	      }
3870	    } else if (carBehind && carBehind.aggression > 0.5 && ai.aggression > 0.3 && !offTrack) {
3871	      /* Defensive driving: block if someone aggressive is behind */
3872	      ai.state = 'defending';
3873	      ai.defendAgainst = carBehind;
3874	    } else {
3875	      ai.state = 'racing';
3876	      ai.overtakeTarget = null;
3877	      ai.defendAgainst = null;
3878	    }
3879	
3880	    /* State timer tracking */
3881	    if (ai.state === 'overtaking') {
3882	      ai.stateTimer++;
3883	    } else if (ai.state === 'defending') {
3884	      ai.stateTimer++;
3885	    } else {
3886	      ai.stateTimer = 0;
3887	    }
3888	  }
3889	
3890	  /**
3891	   * Find the nearest car ahead of this AI within range.
3892	   * @param {object} ai
3893	   * @param {object[]} allCars
3894	   * @param {number} range
3895	   * @returns {object|null}
3896	   */
3897	  function findCarAhead(ai, allCars, range) {
3898	    let closest = null;
3899	    let closestDist = range;
3900	    for (let i = 0; i < allCars.length; i++) {
3901	      const other = allCars[i];
3902	      if (other === ai) { continue; }
3903	      if (other.finished) { continue; }
3904	      const dz = other.z - ai.z;
3905	      if (dz > 0 && dz < range) {
3906	        const dx = Math.abs(other.x - ai.x);
3907	        if (dx < 50 && dz < closestDist) {
3908	          closestDist = dz;
3909	          closest = other;
3910	        }
3911	      }
3912	    }
3913	    return closest;
3914	  }
3915	
3916	  /**
3917	   * Find the nearest car behind this AI within range.
3918	   * @param {object} ai
3919	   * @param {object[]} allCars
3920	   * @param {number} range
3921	   * @returns {object|null}
3922	   */
3923	  function findCarBehind(ai, allCars, range) {
3924	    let closest = null;
3925	    let closestDist = range;
3926	    for (let i = 0; i < allCars.length; i++) {
3927	      const other = allCars[i];
3928	      if (other === ai) { continue; }
3929	      if (other.finished) { continue; }
3930	      const dz = ai.z - other.z;
3931	      if (dz > 0 && dz < range) {
3932	        const dx = Math.abs(other.x - ai.x);
3933	        if (dx < 50 && dz < closestDist) {
3934	          closestDist = dz;
3935	          closest = other;
3936	        }
3937	      }
3938	    }
3939	    return closest;
3940	  }
