3942	  /**
3943	   * Check if an AI car is off the track.
3944	   * @param {object} ai
3945	   * @param {object|null} segInfo
3946	   * @returns {boolean}
3947	   */
3948	  function isOffTrack(ai, segInfo) {
3949	    if (!segInfo) { return false; }
3950	    const seg = segInfo.segment;
3951	    const halfWidth = (seg.width || 120) / 2;
3952	    const centerX = seg.worldX !== undefined ? seg.worldX : 400;
3953	    const distFromCenter = Math.abs(ai.x - centerX);
3954	    return distFromCenter > halfWidth + R.CONFIG.AI_OFFTRACK_THRESHOLD;
3955	  }
