3957	  /* ==========================================================================
3958	     AI Speed Control
3959	     ========================================================================== */
3960	
3961	  /**
3962	   * Control AI speed based on road conditions and state.
3963	   * @param {object} ai
3964	   * @param {number} dt
3965	   * @param {number} upcomingCurv
3966	   * @param {{ x: number, curvature: number }} trackInfo
3967	   */
3968	  function updateAISpeed(ai, dt, upcomingCurv, trackInfo) {
3969	    const brakeCurvThresh = R.CONFIG.AI_BRAKE_CURVATURE_THRESHOLD;
3970	    const brakeHardCurv = R.CONFIG.AI_BRAKE_HARD_CURVATURE;
3971	
3972	    /* Target speed based on upcoming curvature */
3973	    let idealSpeed = ai.maxSpeed;
3974	
3975	    /* Pre-brake for upcoming corners */
3976	    if (upcomingCurv > brakeCurvThresh) {
3977	      /* Skilled drivers brake less before corners */
3978	      const brakeFactor = 1 - (ai.skillLevel * 0.5);
3979	      const curvRatio = clamp(
3980	        (upcomingCurv - brakeCurvThresh) / (brakeHardCurv - brakeCurvThresh),
3981	        0, 1
3982	      );
3983	      const speedReduction = curvRatio * ai.maxSpeed * 0.6 * brakeFactor;
3984	      idealSpeed = ai.maxSpeed - speedReduction;
3985	      /* Hard brake for tight corners */
3986	      if (upcomingCurv > brakeHardCurv * 0.7) {
3987	        idealSpeed = ai.maxSpeed * 0.35 * (1 + ai.skillLevel * 0.5);
3988	      }
3989	    }
3990	
3991	    /* Curve negotiation: skilled drivers can corner faster */
3992	    const currentCurv = Math.abs(trackInfo.curvature);
3993	    if (currentCurv > brakeCurvThresh * 0.3) {
3994	      const cornerSpeedPenalty = currentCurv * 400 * (1 - ai.skillLevel * 0.6);
3995	      idealSpeed = Math.min(idealSpeed, ai.maxSpeed - cornerSpeedPenalty);
3996	    }
3997	
3998	    /* State-specific speed adjustments */
3999	    if (ai.state === 'overtaking') {
4000	      /* Push harder when overtaking */
4001	      idealSpeed = Math.min(idealSpeed * 1.08, ai.maxSpeed * 1.02);
4002	      /* High aggression: more speed, less caution */
4003	      if (ai.aggression > 0.7) {
4004	        idealSpeed *= 1.05;
4005	      }
4006	    } else if (ai.state === 'defending') {
4007	      /* Slightly faster to maintain position */
4008	      idealSpeed = Math.min(idealSpeed * 1.03, ai.maxSpeed * 0.98);
4009	    } else if (ai.state === 'recovering') {
4010	      /* Slow down to regain control */
4011	      idealSpeed = ai.maxSpeed * 0.45;
4012	    }
4013	
4014	    /* Overtaking: steer to inside of approaching curve if car ahead is slower */
4015	    if (ai.state === 'overtaking' && ai.overtakeTarget && trackInfo.curvature !== 0) {
4016	      const curveSign = trackInfo.curvature > 0 ? 1 : -1;
4017	      /* Inside line on curves */
4018	      const insideOffset = -curveSign * 25;
4019	      ai.steerAngle += insideOffset * 0.015 * ai.aggression;
4020	      ai.steerAngle = clamp(ai.steerAngle, -1, 1);
4021	    }
4022	
4023	    /* Defending: block the racing line */
4024	    if (ai.state === 'defending') {
4025	      /* Position car in the middle to block overtaking attempts */
4026	      const segInfo = getSegmentAtZ(ai.z);
4027	      if (segInfo) {
4028	        const centerX = segInfo.segment.worldX || 400;
4029	        if (Math.abs(ai.x - centerX) < 20) {
4030	          /* Stay near center to block the racing line */
4031	          ai.steerAngle *= 0.8;
4032	        }
4033	      }
4034	    }
4035	
4036	    /* ---- Rubber-banding: subtle speed adjustment ---- */
4037	    idealSpeed = applyRubberBanding(ai, idealSpeed);
4038	
4039	    /* ---- Apply acceleration or braking to reach ideal speed ---- */
4040	    ai.targetSpeed = idealSpeed;
4041	    const speedDiff = idealSpeed - ai.speed;
4042	
4043	    if (speedDiff > 0) {
4044	      /* Accelerate */
4045	      ai.speed += ai.acceleration * dt * 60;
4046	      ai.brakeLevel = 0;
4047	    } else {
4048	      /* Brake */
4049	      const brakeForce = ai.braking * (1 + (1 - ai.skillLevel) * 0.5);
4050	      ai.speed += Math.max(speedDiff, -brakeForce * dt * 60);
4051	      ai.brakeLevel = Math.min(1, Math.abs(speedDiff) / ai.maxSpeed * 2);
4052	    }
4053	
4054	    /* Ensure minimum speed */
4055	    if (ai.speed < 0.5 && ai.state !== 'recovering') {
4056	      ai.speed = 0.5;
4057	    }
4058	    ai.speed = clamp(ai.speed, 0, ai.maxSpeed * 1.1);
4059	  }
