4061	  /**
4062	   * Subtle rubber-banding: AI speeds up slightly if player is far ahead,
4063	   * slows down slightly if player is far behind.
4064	   * @param {object} ai
4065	   * @param {number} idealSpeed
4066	   * @returns {number} adjusted speed
4067	   */
4068	  function applyRubberBanding(ai, idealSpeed) {
4069	    const playerCar = R.playerCar;
4070	    if (!playerCar || playerCar.finished) { return idealSpeed; }
4071	
4072	    const aiDist = getTotalDistance(ai);
4073	    const playerDist = getTotalDistance(playerCar);
4074	    const gap = playerDist - aiDist; // positive = player ahead
4075	    const bandRange = R.CONFIG.AI_RUBBERBAND_RANGE;
4076	    const bandFactor = R.CONFIG.AI_RUBBERBAND_FACTOR;
4077	
4078	    if (Math.abs(gap) > bandRange) {
4079	      if (gap > 0) {
4080	        /* Player is far ahead — AI gets a slight boost */
4081	        return idealSpeed * (1 + bandFactor);
4082	      } else {
4083	        /* Player is far behind — AI slows a tiny bit */
4084	        return idealSpeed * (1 - bandFactor * 0.5);
4085	      }
4086	    }
4087	    return idealSpeed;
4088	  }
