4103	  /* ==========================================================================
4104	     Car Physics (mirrors player physics)
4105	     ========================================================================== */
4106	
4107	  /**
4108	   * Apply the same car physics as the player to an AI car.
4109	   * Updates ai.x, ai.z, ai.angle, ai.speed, ai.driftFactor.
4110	   * @param {object} car — AI car (or player car shape)
4111	   * @param {number} dt
4112	   */
4113	  function applyCarPhysics(car, dt) {
4114	    const speed = car.speed || 0;
4115	    const steer = car.steerAngle || 0;
4116	    const handling = car.handling || 0.04;
4117	
4118	    if (speed < 0.01 && (R.input && R.input.throttle === 0)) {
4119	      car.driftFactor = 0;
4120	      return;
4121	    }
4122	
4123	    /* Friction */
4124	    const friction = 0.98;
4125	    car.speed *= friction;
4126	
4127	    /* Drift physics */
4128	    const steerStrength = steer * handling * speed * 0.5;
4129	    car.driftFactor += steerStrength;
4130	    car.driftFactor *= 0.96; // drift recovery
4131	    car.driftFactor = clamp(car.driftFactor, -speed * 0.35, speed * 0.35);
4132	
4133	    /* Update angle */
4134	    car.angle += car.driftFactor * dt * 3;
4135	
4136	    /* Update position */
4137	    const forwardX = Math.sin(car.angle) * car.speed * dt * 60;
4138	    const forwardZ = Math.cos(car.angle) * car.speed * dt * 60;
4139	
4140	    car.x += forwardX;
4141	    car.z += forwardZ;
4142	
4143	    /* Update distance tracking */
4144	    car.totalDistance = getTotalDistance(car);
4145	
4146	    /* Clamp speed */
4147	    car.speed = clamp(car.speed, 0, car.maxSpeed * 1.15);
4148	  }
