4151	     Lap / Checkpoint tracking
4152	     ========================================================================== */
4153	
4154	  /**
4155	   * Track lap progress and checkpoint crossing.
4156	   * @param {object} ai
4157	   */
4158	  function updateAILapProgress(ai) {
4159	    const tLen = trackLength();
4160	    if (tLen <= 0) { return; }
4161	
4162	    /* Detect lap crossing */
4163	    const prevZ = ai.prevWorldZ || ai.z;
4164	    if (prevZ < tLen * 0.5 && ai.z >= tLen * 0.9) {
4165	      /* Wrapped around? Check if close to track length */
4166	    }
4167	    if (ai.z >= tLen) {
4168	      ai.lap = (ai.lap || 0) + 1;
4169	      ai.z -= tLen;
4170	      const total = R.track.totalLaps || 3;
4171	      const segs = R.track.segments;
4172	      if (!segs) return;
4173	      if (ai.lap >= total) {
4174	        ai.finished = true;
4175	        ai.speed = 0;
4176	      }
4177	    } else if (ai.z < 0 && (ai.lap || 0) > 0) {
4178	      /* Crossed finish line going forward */
4179	      const total = R.track.totalLaps || 3;
4180	      if (ai.lap >= total) {
4181	        ai.finished = true;
4182	        ai.speed = 0;
4183	        ai.z = tLen;
4184	      }
4185	    }
4186	    ai.prevWorldZ = ai.z;
4187	  }
