4193	  /**
4194	   * Steer back toward the track when off-road.
4195	   * @param {object} ai
4196	   * @param {number} dt
4197	   */
4198	  function handleOffTrack(ai, dt) {
4199	    const segInfo = getSegmentAtZ(ai.z);
4200	    if (!segInfo) { return; }
4201	
4202	    const centerX = segInfo.segment.worldX !== undefined ? segInfo.segment.worldX : 400;
4203	    const halfWidth = (segInfo.segment.width || 120) / 2;
4204	    const distFromCenter = Math.abs(ai.x - centerX);
4205	
4206	    if (distFromCenter > halfWidth + 15) {
4207	      ai.state = 'recovering';
4208	      ai.recoveryTimer = Math.max(ai.recoveryTimer, 30);
4209	      /* Reduce speed on rough ground */
4210	      const offTrackPenalty = 1 - Math.min((distFromCenter - halfWidth) / 100, 0.6);
4211	      ai.speed *= lerp(offTrackPenalty, 1, 0.1);
4212	      /* Steer toward track center */
4213	      const toCenter = centerX - ai.x;
4214	      const steerCorrection = clamp(toCenter * 0.02, -0.5, 0.5);
4215	      ai.steerAngle = lerp(ai.steerAngle, steerCorrection, 0.15);
4216	    }
4217	  }
