4668	// ─── Constants (extend R.CONFIG) ───────────────────────────────────────────
4669	
4670	R.CONFIG.CAR_WIDTH            = R.CONFIG.CAR_WIDTH            || 40;
4671	R.CONFIG.CAR_HEIGHT           = R.CONFIG.CAR_HEIGHT           || 70;
