4682	// ─── Helpers ───────────────────────────────────────────────────────────────
4683	
4684	/**
4685	 * Rotate a point (px, py) around origin (ox, oy) by angle (radians).
4686	 */
4687	R._rotatePoint = function(px, py, ox, oy, angle) {
4688	  const cos = Math.cos(angle);
4689	  const sin = Math.sin(angle);
4690	  const dx = px - ox;
4691	  const dy = py - oy;
4692	  return {
4693	    x: ox + dx * cos - dy * sin,
4694	    y: oy + dx * sin + dy * cos
4695	  };
4696	};
4697	
4698	/**
4699	 * Project polygon points onto an axis. Returns { min, max }.
4700	 */
4701	R._projectPolygon = function(points, axisX, axisY) {
4702	  let min = Infinity;
4703	  let max = -Infinity;
4704	  for (let i = 0; i < points.length; i++) {
4705	    const dot = points[i].x * axisX + points[i].y * axisY;
4706	    if (dot < min) min = dot;
4707	    if (dot > max) max = dot;
4708	  }
4709	  return { min, max };
4710	};
4711	
4712	/**
4713	 * Get the 4 corner points of a car as a rotated rectangle.
4714	 * Car origin (x, y) is the center of the rectangle.
4715	 */
4716	R._getCarCorners = function(car) {
4717	  const hw = R.CONFIG.CAR_WIDTH * 0.5;
4718	  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
4719	  const cx = car.x;
4720	  const cy = car.y;
4721	  const angle = car.angle || 0;
4722	
4723	  const local = [
4724	    { x: -hw, y: -hh },
4725	    { x:  hw, y: -hh },
4726	    { x:  hw, y:  hh },
4727	    { x: -hw, y:  hh }
4728	  ];
4729	
4730	  const corners = [];
4731	  for (let i = 0; i < 4; i++) {
4732	    corners.push(R._rotatePoint(
4733	      cx + local[i].x, cy + local[i].y, cx, cy, angle
4734	    ));
4735	  }
4736	  return corners;
4737	};
4738	
4739	/**
4740	 * Get edge normals of a polygon for SAT (perpendicular to each edge, normalized).
4741	 */
4742	R._getNormals = function(corners) {
4743	  const normals = [];
4744	  for (let i = 0; i < corners.length; i++) {
4745	    const j = (i + 1) % corners.length;
4746	    const edgeX = corners[j].x - corners[i].x;
4747	    const edgeY = corners[j].y - corners[i].y;
4748	    const len = Math.sqrt(edgeX * edgeX + edgeY * edgeY);
4749	    if (len < 0.0001) continue;
4750	    normals.push({ x: -edgeY / len, y: edgeX / len });
4751	  }
4752	  return normals;
4753	};
4754	
4755	/**
4756	 * Overlap amount on an axis between two projections.
4757	 * Positive = overlapping, negative/zero = separated.
4758	 */
4759	R._overlapOnAxis = function(projA, projB) {
4760	  return Math.min(projA.max, projB.max) - Math.max(projA.min, projB.min);
4761	};
4762	
4763	// ─── AABB ───────────────────────────────────────────────────────────────────
4764	
4765	/**
4766	 * Axis-aligned bounding box for a car. Uses max extent of the rotated rectangle
4767	 * (a conservative circle-bounds approximation).
4768	 *
4769	 * @param {Object} car — { x, y, angle }
4770	 * @returns {{ minX: number, maxX: number, minY: number, maxY: number }}
4771	 */
4772	R.carAABB = function(car) {
4773	  const hw = R.CONFIG.CAR_WIDTH * 0.5;
4774	  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
4775	  const angle = car.angle || 0;
4776	  const absCos = Math.abs(Math.cos(angle));
4777	  const absSin = Math.abs(Math.sin(angle));
4778	  const radiusX = hw * absCos + hh * absSin;
4779	  const radiusY = hw * absSin + hh * absCos;
4780	
4781	  return {
4782	    minX: car.x - radiusX,
4783	    maxX: car.x + radiusX,
4784	    minY: car.y - radiusY,
4785	    maxY: car.y + radiusY
4786	  };
4787	};
4788	
4789	/**
4790	 * Test if two AABBs overlap.
4791	 */
4792	R._aabbOverlap = function(a, b) {
4793	  return a.minX < b.maxX && a.maxX > b.minX && a.minY < b.maxY && a.maxY > b.minY;
4794	};
