4796	// ─── Car-to-Car Collision (SAT) ─────────────────────────────────────────────
4797	
4798	/**
4799	 * Detailed collision detection between two cars using Separating Axis Theorem.
4800	 * Each car is a 40x70 rotated rectangle.
4801	 *
4802	 * @param {Object} carA
4803	 * @param {Object} carB
4804	 * @returns {{ hit: boolean, overlapX: number, overlapY: number, depth: number } | null}
4805	 */
4806	R.checkCarToCar = function(carA, carB) {
4807	  // Broad phase: AABB
4808	  if (!R._aabbOverlap(R.carAABB(carA), R.carAABB(carB))) {
4809	    return null;
4810	  }
4811	
4812	  // Narrow phase: SAT
4813	  const cornersA = R._getCarCorners(carA);
4814	  const cornersB = R._getCarCorners(carB);
4815	  const axes = R._getNormals(cornersA).concat(R._getNormals(cornersB));
4816	
4817	  let minOverlap = Infinity;
4818	  let minAxisX = 0;
4819	  let minAxisY = 0;
4820	
4821	  for (let i = 0; i < axes.length; i++) {
4822	    const ax = axes[i].x;
4823	    const ay = axes[i].y;
4824	    const projA = R._projectPolygon(cornersA, ax, ay);
4825	    const projB = R._projectPolygon(cornersB, ax, ay);
4826	    const overlap = R._overlapOnAxis(projA, projB);
4827	
4828	    if (overlap <= 0) return null; // separating axis found
4829	
4830	    if (overlap < minOverlap) {
4831	      minOverlap = overlap;
4832	      minAxisX = ax;
4833	      minAxisY = ay;
4834	    }
4835	  }
4836	
4837	  return {
4838	    hit: true,
4839	    overlapX: minAxisX * minOverlap,
4840	    overlapY: minAxisY * minOverlap,
4841	    depth: minOverlap
4842	  };
4843	};
