4845	// ─── Collision Resolution ───────────────────────────────────────────────────
4846	
4847	/**
4848	 * Resolve a collision between two cars: push apart and adjust velocities.
4849	 *
4850	 * Push ratios:
4851	 *   - Both moving: 50% each
4852	 *   - One stationary (speed < MIN_SPEED): stationary car gets 70% push,
4853	 *     moving car takes 30%
4854	 *
4855	 * Velocity impulse:
4856	 *   - Relative velocity along collision normal
4857	 *   - Equal-mass damped exchange
4858	 *   - COLLISION_DAMPING applied to both cars' speed
4859	 *
4860	 * @param {Object} carA
4861	 * @param {Object} carB
4862	 * @param {{ overlapX: number, overlapY: number, depth: number }} overlap
4863	 */
4864	R.resolveCollision = function(carA, carB, overlap) {
4865	  const depth = overlap.depth;
4866	  if (depth <= 0) return;
4867	
4868	  const speedA = Math.abs(carA.speed || 0);
4869	  const speedB = Math.abs(carB.speed || 0);
4870	  const aStationary = speedA < R.CONFIG.MIN_SPEED;
4871	  const bStationary = speedB < R.CONFIG.MIN_SPEED;
4872	
4873	  // Determine push ratios
4874	  let pushRatioA, pushRatioB;
4875	  if (aStationary && !bStationary) {
4876	    pushRatioA = 0.7; pushRatioB = 0.3;
4877	  } else if (bStationary && !aStationary) {
4878	    pushRatioA = 0.3; pushRatioB = 0.7;
4879	  } else {
4880	    pushRatioA = 0.5; pushRatioB = 0.5;
4881	  }
4882	
4883	  // Push apart
4884	  carA.x -= overlap.overlapX * pushRatioA;
4885	  carA.y -= overlap.overlapY * pushRatioA;
4886	  carB.x += overlap.overlapX * pushRatioB;
4887	  carB.y += overlap.overlapY * pushRatioB;
4888	
4889	  // Velocity exchange
4890	  const nx = overlap.overlapX / (depth || 0.001);
4891	  const ny = overlap.overlapY / (depth || 0.001);
4892	
4893	  const vAx = Math.cos(carA.angle || 0) * (carA.speed || 0);
4894	  const vAy = Math.sin(carA.angle || 0) * (carA.speed || 0);
4895	  const vBx = Math.cos(carB.angle || 0) * (carB.speed || 0);
4896	  const vBy = Math.sin(carB.angle || 0) * (carB.speed || 0);
4897	
4898	  const relVelN = (vAx - vBx) * nx + (vAy - vBy) * ny;
4899	
4900	  // Only resolve if cars are approaching
4901	  if (relVelN > 0) {
4902	    if (!aStationary && !bStationary) {
4903	      // Equal-mass damped exchange: each car moves toward average speed
4904	      const avgSpeed = (carA.speed + carB.speed) / 2;
4905	      carA.speed = avgSpeed - (carA.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
4906	      carB.speed = avgSpeed - (carB.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
4907	    } else if (aStationary) {
4908	      carB.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
4909	      carA.speed = carB.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
4910	    } else {
4911	      carA.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
4912	      carB.speed = carA.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
4913	    }
4914	
4915	    // Both lose energy
4916	    carA.speed *= R.CONFIG.COLLISION_DAMPING;
4917	    carB.speed *= R.CONFIG.COLLISION_DAMPING;
4918	  }
4919	
4920	  // Clamp tiny speeds to zero
4921	  if (Math.abs(carA.speed) < R.CONFIG.MIN_SPEED * 0.5) carA.speed = 0;
4922	  if (Math.abs(carB.speed) < R.CONFIG.MIN_SPEED * 0.5) carB.speed = 0;
4923	};
