4938	 */
4939	R.checkCarToBoundary = function(car, dt) {
4940	  if (typeof R.isOnTrack !== 'function') return;
4941	
4942	  const carZ = (car.z !== undefined) ? car.z : 0;
4943	  if (R.isOnTrack(car.x, carZ)) {
4944	    car._offTrack = false;
4945	    car._offTrackDepth = 0;
