5010	R.checkCollisions = function() {
5011	  R._collisionCountThisFrame = 0;
5012	  R._lastCollisionInfo = null;
5013	
5014	  if (R.state.phase !== 'racing') return;
5015	
5016	  // 1. Gather cars
5017	  const cars = [];
5018	  if (R.playerCar) cars.push(R.playerCar);
5019	  if (R.aiCars && R.aiCars.length > 0) {
5020	    for (let i = 0; i < R.aiCars.length; i++) cars.push(R.aiCars[i]);
5021	  }
5022	
5023	  if (cars.length < 2) {
5024	    for (let i = 0; i < cars.length; i++) R.checkCarToBoundary(cars[i], 0.016);
5025	    return;
5026	  }
5027	
5028	  // 2. AABB broad phase
5029	  const aabbs = [];
5030	  for (let i = 0; i < cars.length; i++) aabbs.push(R.carAABB(cars[i]));
5031	
5032	  const candidates = [];
5033	  for (let i = 0; i < cars.length; i++) {
5034	    for (let j = i + 1; j < cars.length; j++) {
5035	      if (R._aabbOverlap(aabbs[i], aabbs[j])) {
5036	        candidates.push({ a: cars[i], b: cars[j] });
5037	      }
5038	    }
5039	  }
5040	
5041	  if (candidates.length === 0) {
5042	    for (let i = 0; i < cars.length; i++) R.checkCarToBoundary(cars[i], 0.016);
5043	    return;
5044	  }
5045	
5046	  // 3. SAT narrow phase
