5110	  // 6. Boundary re-check for all cars (collisions may have pushed cars off track)
5111	  const boundaryChecked = {};
5112	
5113	  // Check involved cars first
5114	  for (let k = 0; k < maxResolve; k++) {
5115	    const col = collisions[k];
5116	    const keyA = col.carA._id || 'player';
5117	    const keyB = col.carB._id || 'ai_' + R.aiCars.indexOf(col.carB);
