5126	    }
5127	  }
5128	
5129	  // Then check remaining cars
5130	  for (let i = 0; i < cars.length; i++) {
5131	    const carKey = cars[i]._id || (cars[i] === R.playerCar ? 'player' : 'ai_' + R.aiCars.indexOf(cars[i]));
