5723	  /**
5724	   * R.renderMiniMap()
5725	   * Bottom-right corner, 140x140 pixels.
5726	   * Simplified track outline + all cars as dots + player as pulsing dot.
5727	   */
5728	  R.renderMiniMap = function () {
5729	    var ctx  = R.ctx;
5730	    var mx   = CFG.HUD.MINIMAP_X;
5731	    var my   = CFG.HUD.MINIMAP_Y;
5732	    var size = CFG.HUD.MINIMAP_SIZE;
5733	
5734	    // Draw onto offscreen canvas first
5735	    var mCtx = _minimapCtx;
5736	    var w = size, h = size;
5737	
5738	    // Clear offscreen
5739	    mCtx.clearRect(0, 0, w, h);
5740	
5741	    // Background
5742	    mCtx.fillStyle = 'rgba(10,10,10,0.8)';
5743	    mCtx.fillRect(0, 0, w, h);
5744	    mCtx.strokeStyle = 'rgba(255,255,255,0.2)';
5745	    mCtx.lineWidth = 1.5;
5746	    mCtx.strokeRect(0, 0, w, h);
5747	
5748	    // Compute track bounds
5749	    var track = R.track;
5750	    if (!track || !track.segments || track.segments.length === 0) {
5751	      // Draw empty minimap to screen
5752	      ctx.drawImage(_minimapCanvas, mx, my);
5753	      return;
5754	    }
5755	
5756	    var segs = track.segments;
5757	    var minX = Infinity, maxX = -Infinity;
5758	    var minY = Infinity, maxY = -Infinity;
5759	    var points = [];
5760	    for (var i = 0; i < segs.length; i++) {
5761	      var sx = segs[i].worldX || 0;
5762	      var sy = segs[i].worldY || 0;
5763	      points.push({ x: sx, y: sy });
5764	      if (sx < minX) minX = sx;
5765	      if (sx > maxX) maxX = sx;
5766	      if (sy < minY) minY = sy;
5767	      if (sy > maxY) maxY = sy;
5768	    }
5769	
5770	    // Pad bounds
5771	    var rangeX = maxX - minX || 1;
5772	    var rangeY = maxY - minY || 1;
5773	    var maxRange = Math.max(rangeX, rangeY);
