5796	    mCtx.lineCap   = 'round';
5797	    mCtx.lineJoin  = 'round';
5798	
5799	    for (var tSeg = 1; tSeg < points.length; tSeg++) {
5800	      var p0 = points[tSeg - 1];
5801	      var p1 = points[tSeg];
5802	      var x0 = toMapX(p0.x), y0 = toMapY(p0.y);
5803	      var x1 = toMapX(p1.x), y1 = toMapY(p1.y);
5804	
5805	      // Gradient based on track progress (lighter at start, dimmer toward end)
5806	      var frac = tSeg / points.length;
5807	      var gAlpha = 0.25 + frac * 0.35;
5808	
5809	      mCtx.beginPath();
5810	      mCtx.moveTo(x0, y0);
5811	      mCtx.lineTo(x1, y1);
5812	      mCtx.strokeStyle = 'rgba(255,255,255,' + gAlpha.toFixed(2) + ')';
5813	      mCtx.stroke();
5814	    }
5815	
5816	    // Draw road width as subtle parallel lines
5817	    mCtx.lineWidth = 1;
5818	    for (var rSeg = 1; rSeg < points.length; rSeg++) {
