5838	    }
5839	
5840	    // Draw all cars as dots
5841	    var cars = R.cars || [];
5842	    var playerIdx = -1;
5843	    for (var c = 0; c < cars.length; c++) {
5844	      if (cars[c] === R.player) { playerIdx = c; break; }
5845	    }
5846	
5847	    for (var ci = 0; ci < cars.length; ci++) {
5848	      var car = cars[ci];
5849	      var cmx = toMapX(car.x || 0);
5850	      var cmy = toMapY(car.y || 0);
