5858	      mCtx.strokeStyle = 'rgba(0,0,0,0.5)';
5859	      mCtx.lineWidth = 0.8;
5860	      mCtx.stroke();
5861	    }
5862	
5863	    // Draw player car as larger pulsing dot
5864	    if (playerIdx >= 0 && R.player) {
