5875	
5876	      // Main dot
5877	      mCtx.beginPath();
5878	      mCtx.arc(pmx, pmy, pRad, 0, Math.PI * 2);
5879	      mCtx.fillStyle = '#ffff44';
5880	      mCtx.fill();
5881	      mCtx.strokeStyle = '#ffffff';
5882	      mCtx.lineWidth = 1.2;
5883	      mCtx.stroke();
5884	    }
5885	
5886	    // Draw to screen
5887	    ctx.drawImage(_minimapCanvas, mx, my);
5888	
5889	    // "MAP" label above the minimap
5890	    ctx.font         = 'bold 10px Arial, sans-serif';
5891	    ctx.fillStyle    = 'rgba(255,255,255,0.4)';
5892	    ctx.textAlign    = 'left';
5893	    ctx.textBaseline = 'bottom';
5894	    ctx.fillText('MAP', mx + 2, my - 3);
5895	  };
