5987	    // Clamp to [-1, 1]
5988	    driftAmt = Math.max(-1, Math.min(1, driftAmt));
5989	
5990	    var absDrift = Math.abs(driftAmt);
5991	    var barHalf  = bw / 2;
5992	
5993	    ctx.save();
5994	
5995	    // Background bar (dark)
5996	    var bgX = dx - barHalf;
5997	    var bgY = dy;
5998	    ctx.fillStyle = 'rgba(30,30,30,0.7)';
5999	    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
6000	    ctx.lineWidth = 1;
