6011	    // Active drift fill
6012	    if (absDrift > 0.005) {
6013	      // Color based on drift intensity
6014	      var r, g, bVal;
6015	      if (absDrift < 0.4) {
6016	        // white → yellow
6017	        var t = absDrift / 0.4;
6018	        r = 255;
6019	        g = 255 - t * 55;
6020	        bVal = 255 - t * 200;
6021	      } else if (absDrift < 0.75) {
6022	        // yellow → orange
6023	        var t2 = (absDrift - 0.4) / 0.35;
6024	        r = 255;
6025	        g = 200 - t2 * 100;
6026	        bVal = 55 - t2 * 55;
6027	      } else {
6028	        // orange
6029	        r = 255;
6030	        g = 100;
6031	        bVal = 0;
6032	      }
6033	      var driftColor = 'rgb(' + Math.round(r) + ',' + Math.round(g) + ',' + Math.round(bVal) + ')';
6034	
6035	      var fillHalf = barHalf * absDrift;
6036	      var fillX, fillW;
6037	
6038	      if (driftAmt > 0) {
6039	        // Drift right
6040	        fillX = dx;
6041	        fillW = fillHalf;
6042	      } else {
6043	        // Drift left
6044	        fillX = dx - fillHalf;
6045	        fillW = fillHalf;
6046	      }
