6059	    ctx.fillStyle    = 'rgba(255,255,255,0.5)';
6060	    ctx.textAlign    = 'center';
6061	    ctx.textBaseline = 'top';
6062	    ctx.fillText('DRIFT', dx, bgY + bh + 3);
