6306	  /**
6307	   * _buildResultsTable()
6308	   * Internal: build the sorted results snapshot for the race-results overlay.
6309	   * @returns {Array<Object>} sorted list of result entries
6310	   */
6311	  function _buildResultsTable() {
6312	    var cars  = R.cars || [];
6313	    var track = R.track;
6314	    var totalLaps = (track && track.totalLaps) || 3;
6315	    var entries = [];
6316	
6317	    for (var i = 0; i < cars.length; i++) {
6318	      var car = cars[i];
6319	      var finished = car.finished || false;
6320	      var lap      = car.lap || 0;
6321	      var timeStr  = 'DNF';
6322	
6323	      if (finished) {
6324	        timeStr = _formatTime(car.finishTime || 0);
6325	      } else if (lap >= totalLaps) {
6326	        timeStr = 'DONE';
6327	      }
6328	
6329	      entries.push({
6330	        _carIndex:  i,
6331	        _isPlayer:  car === R.player,
6332	        _color:     car.color || '#aaaaaa',
6333	        _name:      car === R.player ? 'YOU' : (car.driverName || ('Car ' + (i + 1))),
6334	        _lap:       lap,
6335	        _finished:  finished,
6336	        _finishTime: car.finishTime || 0,
6337	        _timeStr:   timeStr
6338	      });
6339	    }
6340	
6341	    // Sort: finished cars first (by finishTime asc), then by lap desc, then by checkpoint/x
6342	    entries.sort(function (a, b) {
6343	      if (a._finished && b._finished) {
6344	        return a._finishTime - b._finishTime;
6345	      }
6346	      if (a._finished) return -1;
6347	      if (b._finished) return 1;
6348	      if (a._lap !== b._lap) return b._lap - a._lap;
6349	
6350	      var carA = R.cars[a._carIndex];
6351	      var carB = R.cars[b._carIndex];
6352	      var lapA = carA ? (carA.checkpointIdx || 0) : 0;
6353	      var lapB = carB ? (carB.checkpointIdx || 0) : 0;
6354	      if (lapA !== lapB) return lapB - lapA;
6355	
6356	      var xA = carA ? (carA.x || 0) : 0;
6357	      var xB = carB ? (carB.x || 0) : 0;
6358	      return xB - xA;
6359	    });
6360	
6361	    return entries;
6362	  }
