6364	  /**
6365	   * R.sortCarsByPosition()
6366	   * Sort cars by race position: finished first, then by lap/checkpoint.
6367	   * Used by both HUD and potentially other systems.
6368	   * Each entry gets a _carIndex property so HUD can map back to R.cars.
6369	   * @returns {Array<Object>} sorted list
6370	   */
6371	  R.sortCarsByPosition = function () {
6372	    var cars  = R.cars || [];
6373	    var track = R.track;
6374	    var totalLaps = (track && track.totalLaps) || 3;
6375	    var entries = [];
6376	
6377	    for (var i = 0; i < cars.length; i++) {
6378	      var car = cars[i];
6379	      entries.push({
6380	        _carIndex:  i,
6381	        _isPlayer:  car === R.player,
6382	        _lap:       car.lap || 0,
6383	        _finished:  car.finished || false,
6384	        _finishTime: car.finishTime || 0,
6385	        _checkpointIdx: car.checkpointIdx || 0,
6386	        _x:         car.x || 0,
6387	        _y:         car.y || 0
6388	      });
6389	    }
6390	
6391	    entries.sort(function (a, b) {
6392	      if (a._finished && b._finished) {
6393	        return a._finishTime - b._finishTime;
6394	      }
6395	      if (a._finished) return -1;
6396	      if (b._finished) return 1;
6397	      if (a._lap !== b._lap) return b._lap - a._lap;
6398	      if (a._checkpointIdx !== b._checkpointIdx) {
6399	        return b._checkpointIdx - a._checkpointIdx;
6400	      }
6401	      return b._x - a._x;
6402	    });
6403	
6404	    return entries;
6405	  };
