6409	  /**
6410	   * _formatTime(seconds)
6411	   * Format a time value in seconds as M:SS.mmm.
6412	   * @param {number} sec
6413	   * @returns {string}
6414	   */
6415	  function _formatTime(sec) {
6416	    if (sec == null || isNaN(sec)) return '--';
6417	    var m = Math.floor(sec / 60);
6418	    var s = Math.floor(sec % 60);
6419	    var ms = Math.floor((sec % 1) * 1000);
6420	    return m + ':' +
6421	      (s < 10 ? '0' : '') + s + '.' +
6422	      (ms < 100 ? (ms < 10 ? '00' : '0') : '') + ms;
6423	  }
