6425	  /**
6426	   * R._roundRect(ctx, x, y, w, h, r)
6427	   * Draw a filled rounded rectangle.
6428	   */
6429	  R._roundRect = function (ctx, x, y, w, h, r) {
6430	    ctx.beginPath();
6431	    R._roundRectPath(ctx, x, y, w, h, r);
6432	    ctx.fill();
6433	    ctx.stroke();
6434	  };
6435	
6436	  /**
6437	   * R._roundRectPath(ctx, x, y, w, h, r)
6438	   * Add a rounded rectangle path to the current context.
6439	   */
6440	  R._roundRectPath = function (ctx, x, y, w, h, r) {
6441	    r = Math.min(r, w / 2, h / 2);
6442	    ctx.beginPath();
6443	    ctx.moveTo(x + r, y);
6444	    ctx.lineTo(x + w - r, y);
6445	    ctx.arcTo(x + w, y, x + w, y + r, r);
6446	    ctx.lineTo(x + w, y + h - r);
6447	    ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
6448	    ctx.lineTo(x + r, y + h);
6449	    ctx.arcTo(x, y + h, x, y + h - r, r);
6450	    ctx.lineTo(x, y + r);
6451	    ctx.arcTo(x, y, x + r, y, r);
6452	    ctx.closePath();
6453	  };
6454	
6455	  /**
6456	   * R._roundRectStroke(ctx, x, y, w, h, r)
6457	   * Stroke-only rounded rectangle.
6458	   */
6459	  R._roundRectStroke = function (ctx, x, y, w, h, r) {
6460	    ctx.beginPath();
6461	    R._roundRectPath(ctx, x, y, w, h, r);
6462	    ctx.stroke();
6463	  };
