9182	/**
9183	 * Draw a rounded rectangle path (must be wrapped in beginPath/fill/stroke by caller).
9184	 * @param {CanvasRenderingContext2D} ctx
9185	 * @param {number} x
9186	 * @param {number} y
9187	 * @param {number} w
9188	 * @param {number} h
9189	 * @param {number} r - corner radius
9190	 */
9191	function _roundRect(ctx, x, y, w, h, r) {
9192	  ctx.beginPath();
9193	  ctx.moveTo(x + r, y);
9194	  ctx.lineTo(x + w - r, y);
9195	  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
9196	  ctx.lineTo(x + w, y + h - r);
9197	  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
9198	  ctx.lineTo(x + r, y + h);
9199	  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
9200	  ctx.lineTo(x, y + r);
9201	  ctx.quadraticCurveTo(x, y, x + r, y);
9202	  ctx.closePath();
9203	}
