9205	/**
9206	 * Format seconds into MM:SS.ms display string.
9207	 * @param {number} totalSec
9208	 * @returns {string}
9209	 */
9210	function _formatRaceTime(totalSec) {
9211	  if (totalSec == null || !isFinite(totalSec)) return '--:--.--';
9212	  const min = Math.floor(totalSec / 60);
9213	  const sec = Math.floor(totalSec % 60);
9214	  const ms = Math.floor((totalSec % 1) * 100);
9215	  return String(min).padStart(2, '0') + ':' +
9216	         String(sec).padStart(2, '0') + '.' +
9217	         String(ms).padStart(2, '0');
9218	}
9219	
9220	/**
9221	 * Ordinal suffix for position numbers.
9222	 * @param {number} n
9223	 * @returns {string}
9224	 */
9225	function _ordinal(n) {
9226	  if (n === 1) return '1st';
9227	  if (n === 2) return '2nd';
9228	  if (n === 3) return '3rd';
9229	  return n + 'th';
9230	}
