9232	/**
9233	 * Simple ease-out cubic.
9234	 * @param {number} t - progress [0, 1]
9235	 * @returns {number}
9236	 */
9237	function _easeOutCubic(t) {
9238	  return 1 - Math.pow(1 - t, 3);
9239	}
