9270	  const hlH = 1;
9271	  ctx.save();
9272	  ctx.beginPath();
9273	  ctx.rect(x + MC.PANEL_ROUND, hlY, w - MC.PANEL_ROUND * 2, hlH);
9274	  ctx.clip();
9275	  ctx.fillStyle = 'rgba(255,255,255,0.06)';
9276	  ctx.fillRect(x, hlY, w, hlH);
