9282	/**
9283	 * R.drawButton(x, y, w, h, text, color)
9284	 * Draw a styled button: rounded rect, gradient fill, border highlight, centered text.
9285	 * @param {number} x
9286	 * @param {number} y
9287	 * @param {number} w
9288	 * @param {number} h
9289	 * @param {string} text
9290	 * @param {string} [color='#445577'] - base fill color
9291	 */
9292	R.drawButton = function(x, y, w, h, text, color) {
9293	  const ctx = R.ctx;
9294	  const baseColor = color || '#445577';
9295	
9296	  ctx.save();
9297	  _roundRect(ctx, x, y, w, h, MC.BUTTON_ROUND);
9298	
9299	  // Gradient fill (lighter top, darker bottom)
9300	  const grad = ctx.createLinearGradient(x, y, x, y + h);
9301	  grad.addColorStop(0, baseColor);
9302	  grad.addColorStop(1, _darkenColor(baseColor, 0.45));
9303	  ctx.fillStyle = grad;
9304	  ctx.fill();
9305	
9306	  // Border highlight (top edge lighter)
9307	  ctx.strokeStyle = _lightenColor(baseColor, 0.3);
9308	  ctx.lineWidth = 2;
9309	  ctx.stroke();
9310	
9311	  // Inner top highlight line
9312	  ctx.save();
9313	  ctx.beginPath();
9314	  ctx.rect(x + MC.BUTTON_ROUND, y + 1, w - MC.BUTTON_ROUND * 2, 2);
9315	  ctx.clip();
9316	  ctx.fillStyle = 'rgba(255,255,255,0.18)';
9317	  ctx.fillRect(x, y, w, 3);
9318	  ctx.restore();
9319	
9320	  // Text centered
9321	  const fontSize = Math.max(12, Math.min(h * 0.45, 22));
9322	  ctx.fillStyle = '#ffffff';
9323	  ctx.font = 'bold ' + fontSize + 'px "Segoe UI",Arial,sans-serif';
9324	  ctx.textAlign = 'center';
9325	  ctx.textBaseline = 'middle';
9326	  ctx.shadowColor = 'rgba(0,0,0,0.5)';
9327	  ctx.shadowBlur = 2;
9328	  ctx.fillText(text, x + w / 2, y + h / 2);
9329	  ctx.shadowBlur = 0;
9330	
9331	  ctx.restore();
9332	};
