9334	/**
9335	 * R.drawGradientText(text, x, y, colorTop, colorBottom, font)
9336	 * Draw text with a vertical gradient fill using clip region + gradient.
9337	 * @param {string} text
9338	 * @param {number} x - center-x of the text
9339	 * @param {number} y - baseline-y of the text
9340	 * @param {string} colorTop - top gradient color (e.g. '#ffffff')
9341	 * @param {string} colorBottom - bottom gradient color (e.g. '#667799')
9342	 * @param {string} font - CSS font string (e.g. 'bold 96px Arial')
9343	 */
9344	R.drawGradientText = function(text, x, y, colorTop, colorBottom, font) {
9345	  const ctx = R.ctx;
9346	
9347	  ctx.save();
9348	  ctx.font = font;
9349	  ctx.textAlign = 'center';
9350	  ctx.textBaseline = 'alphabetic';
9351	
9352	  // Measure text to build clip region
9353	  const metrics = ctx.measureText(text);
9354	  const tw = metrics.width;
9355	  const th = metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent;
9356	  // Fallback if actualBoundingBox not supported: estimate from font size
9357	  const fontSize = parseInt(font, 10) || 48;
9358	  const textH = th > 0 ? th : fontSize * 1.2;
9359	  const clipX = x - tw / 2 - 4;
9360	  const clipY = y - textH;
9361	
9362	  // Clip to text bounding box
9363	  ctx.beginPath();
9364	  ctx.rect(clipX, clipY, tw + 8, textH + 4);
9365	  ctx.clip();
9366	
9367	  // Vertical gradient
9368	  const grad = ctx.createLinearGradient(0, clipY, 0, clipY + textH);
9369	  grad.addColorStop(0, colorTop);
9370	  grad.addColorStop(1, colorBottom);
9371	  ctx.fillStyle = grad;
9372	  ctx.fillText(text, x, y);
9373	
9374	  ctx.restore();
9375	};
