9379	/**
9380	 * Draw a sports-car silhouette (side-ish view) that can be positioned and scaled.
9381	 * Used by the title screen animation.
9382	 * @param {CanvasRenderingContext2D} ctx
9383	 * @param {number} cx - center x
9384	 * @param {number} cy - center y (bottom of wheels)
9385	 * @param {number} scale - size multiplier
9386	 */
9387	function _drawCarSilhouette(ctx, cx, cy, scale) {
9388	  const s = scale;
9389	  ctx.save();
9390	  ctx.translate(cx, cy);
9391	
9392	  // Car body dimensions (in base units, multiplied by scale)
9393	  const bodyLen = 180 * s;
9394	  const bodyH   = 32 * s;
9395	  const cabinW  = 55 * s;
9396	  const cabinH  = 28 * s;
9397	  const wheelR  = 16 * s;
9398	  const wheelW  = 10 * s;
9399	  const groundY = 0;
9400	
9401	  ctx.fillStyle = '#d0d8e8';
9402	
9403	  // --- Main body (low, wide) ---
9404	  ctx.beginPath();
9405	  ctx.moveTo(-bodyLen * 0.48, groundY - bodyH * 0.35);                // front bumper top
9406	  ctx.lineTo(-bodyLen * 0.38, groundY - bodyH * 0.7);                 // hood rise
9407	  ctx.lineTo(-bodyLen * 0.10, groundY - bodyH * 0.75);                // windshield base
9408	  ctx.lineTo(bodyLen * 0.08, groundY - bodyH * 0.75);                 // rear window base
9409	  ctx.lineTo(bodyLen * 0.35, groundY - bodyH * 0.4);                  // trunk slope
9410	  ctx.lineTo(bodyLen * 0.45, groundY - bodyH * 0.25);                 // rear bumper top
9411	  ctx.lineTo(bodyLen * 0.45, groundY - bodyH * 0.05);                 // rear lower
9412	  ctx.lineTo(-bodyLen * 0.48, groundY - bodyH * 0.05);                // front lower
9413	  ctx.closePath();
9414	  ctx.fill();
9415	
9416	  // --- Cabin / roof ---
9417	  ctx.fillStyle = '#c0c8d8';
9418	  ctx.beginPath();
9419	  ctx.moveTo(-bodyLen * 0.12, groundY - bodyH * 0.75);                // windshield top
9420	  ctx.quadraticCurveTo(-bodyLen * 0.02, groundY - bodyH - cabinH * 0.25, bodyLen * 0.06, groundY - bodyH - cabinH * 0.15); // roof front
9421	  ctx.lineTo(bodyLen * 0.22, groundY - bodyH - cabinH * 0.15);       // roof rear
9422	  ctx.quadraticCurveTo(bodyLen * 0.30, groundY - bodyH - cabinH * 0.1, bodyLen * 0.33, groundY - bodyH * 0.6); // rear window
9423	  ctx.lineTo(-bodyLen * 0.08, groundY - bodyH * 0.7);                // back to windshield
9424	  ctx.closePath();
9425	  ctx.fill();
9426	
9427	  // --- Spoiler ---
9428	  ctx.fillStyle = '#b0b8c8';
9429	  ctx.beginPath();
9430	  ctx.moveTo(bodyLen * 0.40, groundY - bodyH * 0.45);
9431	  ctx.lineTo(bodyLen * 0.48, groundY - bodyH * 0.50);
9432	  ctx.lineTo(bodyLen * 0.48, groundY - bodyH * 0.15);
9433	  ctx.lineTo(bodyLen * 0.43, groundY - bodyH * 0.18);
9434	  ctx.closePath();
9435	  ctx.fill();
9436	
9437	  // --- Front splitter ---
9438	  ctx.fillStyle = '#c8d0e0';
9439	  ctx.beginPath();
9440	  ctx.moveTo(-bodyLen * 0.48, groundY - bodyH * 0.08);
9441	  ctx.lineTo(-bodyLen * 0.44, groundY - bodyH * 0.08);
9442	  ctx.lineTo(-bodyLen * 0.46, groundY + bodyH * 0.02);
9443	  ctx.lineTo(-bodyLen * 0.50, groundY + bodyH * 0.02);
9444	  ctx.closePath();
9445	  ctx.fill();
9446	
9447	  // --- Rear wheel ---
9448	  ctx.fillStyle = '#1a1a1a';
9449	  ctx.beginPath();
9450	  ctx.arc(bodyLen * 0.28, groundY - wheelR * 0.1, wheelR, 0, Math.PI * 2);
9451	  ctx.fill();
9452	  ctx.fillStyle = '#333';
9453	  ctx.beginPath();
9454	  ctx.arc(bodyLen * 0.28, groundY - wheelR * 0.1, wheelR * 0.55, 0, Math.PI * 2);
9455	  ctx.fill();
9456	  // Rim cross
9457	  ctx.strokeStyle = '#555';
9458	  ctx.lineWidth = 1.5 * s;
9459	  ctx.beginPath();
9460	  ctx.moveTo(bodyLen * 0.28 - wheelR * 0.5, groundY - wheelR * 0.1);
9461	  ctx.lineTo(bodyLen * 0.28 + wheelR * 0.5, groundY - wheelR * 0.1);
9462	  ctx.moveTo(bodyLen * 0.28, groundY - wheelR * 0.1 - wheelR * 0.5);
9463	  ctx.lineTo(bodyLen * 0.28, groundY - wheelR * 0.1 + wheelR * 0.5);
9464	  ctx.stroke();
9465	
9466	  // --- Front wheel ---
9467	  ctx.fillStyle = '#1a1a1a';
9468	  ctx.beginPath();
9469	  ctx.arc(-bodyLen * 0.30, groundY - wheelR * 0.1, wheelR, 0, Math.PI * 2);
9470	  ctx.fill();
9471	  ctx.fillStyle = '#333';
9472	  ctx.beginPath();
9473	  ctx.arc(-bodyLen * 0.30, groundY - wheelR * 0.1, wheelR * 0.55, 0, Math.PI * 2);
9474	  ctx.fill();
9475	  ctx.strokeStyle = '#555';
9476	  ctx.lineWidth = 1.5 * s;
9477	  ctx.beginPath();
9478	  ctx.moveTo(-bodyLen * 0.30 - wheelR * 0.5, groundY - wheelR * 0.1);
9479	  ctx.lineTo(-bodyLen * 0.30 + wheelR * 0.5, groundY - wheelR * 0.1);
9480	  ctx.moveTo(-bodyLen * 0.30, groundY - wheelR * 0.1 - wheelR * 0.5);
9481	  ctx.lineTo(-bodyLen * 0.30, groundY - wheelR * 0.1 + wheelR * 0.5);
9482	  ctx.stroke();
9483	
9484	  // --- Window tint (dark) ---
9485	  ctx.fillStyle = 'rgba(20, 25, 40, 0.6)';
9486	  ctx.beginPath();
9487	  ctx.moveTo(-bodyLen * 0.10, groundY - bodyH * 0.73);
9488	  ctx.quadraticCurveTo(-bodyLen * 0.01, groundY - bodyH - cabinH * 0.28, bodyLen * 0.06, groundY - bodyH - cabinH * 0.18);
9489	  ctx.lineTo(bodyLen * 0.20, groundY - bodyH - cabinH * 0.18);
9490	  ctx.quadraticCurveTo(bodyLen * 0.28, groundY - bodyH - cabinH * 0.12, bodyLen * 0.31, groundY - bodyH * 0.62);
9491	  ctx.lineTo(-bodyLen * 0.06, groundY - bodyH * 0.72);
9492	  ctx.closePath();
9493	  ctx.fill();
9494	
9495	  // --- Headlight (front) ---
9496	  ctx.fillStyle = '#ffe8c0';
9497	  ctx.beginPath();
9498	  ctx.ellipse(-bodyLen * 0.47, groundY - bodyH * 0.40, 5 * s, 3 * s, -0.2, 0, Math.PI * 2);
9499	  ctx.fill();
9500	
9501	  // --- Tail light (rear) ---
9502	  ctx.fillStyle = '#ff3333';
9503	  ctx.beginPath();
9504	  ctx.ellipse(bodyLen * 0.44, groundY - bodyH * 0.38, 4 * s, 2.5 * s, 0.1, 0, Math.PI * 2);
9505	  ctx.fill();
9506	
9507	  // --- Exhaust pipes ---
9508	  ctx.fillStyle = '#444';
9509	  ctx.fillRect(bodyLen * 0.42, groundY - bodyH * 0.12, 8 * s, 5 * s);
9510	  ctx.fillRect(bodyLen * 0.42, groundY - bodyH * 0.22, 8 * s, 5 * s);
9511	
9512	  // --- Racing stripe ---
9513	  ctx.fillStyle = 'rgba(255,255,255,0.12)';
9514	  ctx.fillRect(-bodyLen * 0.15, groundY - bodyH * 0.68, bodyLen * 0.42, 5 * s);
9515	
9516	  ctx.restore();
9517	}
