9519	/* =========================== Color Utilities ======================== */
9520	
9521	/**
9522	 * Darken a hex color by a factor (0 = no change, 1 = black).
9523	 * @param {string} hex - e.g. '#445577'
9524	 * @param {number} factor - 0..1
9525	 * @returns {string}
9526	 */
9527	function _darkenColor(hex, factor) {
9528	  const r = parseInt(hex.slice(1, 3), 16);
9529	  const g = parseInt(hex.slice(3, 5), 16);
9530	  const b = parseInt(hex.slice(5, 7), 16);
9531	  const f = 1 - factor;
9532	  return 'rgb(' + Math.floor(r * f) + ',' + Math.floor(g * f) + ',' + Math.floor(b * f) + ')';
9533	}
9534	
9535	/**
9536	 * Lighten a hex color by a factor.
9537	 * @param {string} hex
9538	 * @param {number} factor - 0..1
9539	 * @returns {string}
9540	 */
9541	function _lightenColor(hex, factor) {
9542	  const r = parseInt(hex.slice(1, 3), 16);
9543	  const g = parseInt(hex.slice(3, 5), 16);
9544	  const b = parseInt(hex.slice(5, 7), 16);
9545	  const f = 1 - factor;
9546	  return 'rgb(' +
9547	    Math.floor(r + (255 - r) * factor) + ',' +
9548	    Math.floor(g + (255 - g) * factor) + ',' +
9549	    Math.floor(b + (255 - b) * factor) + ')';
9550	}
