9557	R.renderMenu = function() {
9558	  const ctx = R.ctx;
9559	  const W = R.canvas.width;
9560	  const H = R.canvas.height;
9561	  const time = R.state.time;
9562	
9563	  // Track entrance time for slide-in animations
9564	  if (_menuEntranceTime === 0) {
9565	    _menuEntranceTime = time;
9566	  }
9567	
9568	  // --- 1. Dark background with gradient ---
9569	  const bgGrad = ctx.createLinearGradient(0, 0, 0, H);
9570	  bgGrad.addColorStop(0, MC.BG_COLOR_TOP);
9571	  bgGrad.addColorStop(0.55, '#101030');
9572	  bgGrad.addColorStop(1, MC.BG_COLOR_BOTTOM);
9573	  ctx.fillStyle = bgGrad;
9574	  ctx.fillRect(0, 0, W, H);
9575	
9576	  // Subtle radial glow behind title
9577	  const glowGrad = ctx.createRadialGradient(W / 2, H * 0.28, 0, W / 2, H * 0.28, W * 0.45);
9578	  glowGrad.addColorStop(0, 'rgba(60, 80, 140, 0.18)');
9579	  glowGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
9580	  ctx.fillStyle = glowGrad;
9581	  ctx.fillRect(0, 0, W, H);
9582	
9583	  // --- 2. Title: "ASPHALT LEGENDS" with chrome/gradient effect ---
9584	  const titleY = H * 0.24;
9585	  // Shadow first (drawn behind the gradient text)
9586	  ctx.save();
9587	  ctx.font = MC.TITLE_FONT;
9588	  ctx.textAlign = 'center';
9589	  ctx.textBaseline = 'alphabetic';
9590	  ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
9591	  ctx.fillText('ASPHALT LEGENDS', W / 2 + 3, titleY + 3);
9592	  ctx.restore();
9593	
9594	  // Main chrome gradient text
9595	  R.drawGradientText(
9596	    'ASPHALT LEGENDS',
9597	    W / 2,
9598	    titleY,
9599	    MC.TITLE_COLOR_TOP,
9600	    MC.TITLE_COLOR_BOTTOM,
9601	    MC.TITLE_FONT
9602	  );
9603	
9604	  // Secondary highlight pass: lighter thin stroke at top for chrome effect
9605	  ctx.save();
9606	  ctx.font = MC.TITLE_FONT;
9607	  ctx.textAlign = 'center';
9608	  ctx.textBaseline = 'alphabetic';
9609	  // Clip to top half of text area
9610	  const titleMetrics = ctx.measureText('ASPHALT LEGENDS');
9611	  const titleH = titleMetrics.actualBoundingBoxAscent + titleMetrics.actualBoundingBoxDescent;
9612	  const estTitleH = titleH > 0 ? titleH : MC.TITLE_FONT_SIZE * 1.2;
9613	  const clipTop = titleY - estTitleH;
9614	  ctx.beginPath();
9615	  ctx.rect(0, clipTop, W, estTitleH * 0.45);
9616	  ctx.clip();
9617	  ctx.fillStyle = 'rgba(255, 255, 255, 0.25)';
9618	  ctx.fillText('ASPHALT LEGENDS', W / 2, titleY);
9619	  ctx.restore();
9620	
9621	  // --- 3. Subtitle ---
9622	  const subtitleY = titleY + MC.TITLE_FONT_SIZE * 0.5;
9623	  ctx.fillStyle = MC.SUBTITLE_COLOR;
9624	  ctx.font = MC.SUBTITLE_FONT;
9625	  ctx.textAlign = 'center';
9626	  ctx.textBaseline = 'top';
9627	  ctx.shadowColor = 'rgba(0, 0, 0, 0.4)';
9628	  ctx.shadowBlur = 3;
9629	  ctx.fillText('CANVAS RACING CHAMPIONSHIP', W / 2, subtitleY);
9630	  ctx.shadowBlur = 0;
9631	
9632	  // Decorative line under subtitle
9633	  const lineY = subtitleY + MC.SUBTITLE_FONT_SIZE + 14;
9634	  const lineW = W * 0.25;
9635	  const lineGrad = ctx.createLinearGradient(W / 2 - lineW / 2, 0, W / 2 + lineW / 2, 0);
9636	  lineGrad.addColorStop(0, 'rgba(136, 153, 187, 0)');
9637	  lineGrad.addColorStop(0.5, 'rgba(136, 153, 187, 0.5)');
9638	  lineGrad.addColorStop(1, 'rgba(136, 153, 187, 0)');
9639	  ctx.strokeStyle = lineGrad;
9640	  ctx.lineWidth = 1.5;
9641	  ctx.beginPath();
9642	  ctx.moveTo(W / 2 - lineW / 2, lineY);
9643	  ctx.lineTo(W / 2 + lineW / 2, lineY);
9644	  ctx.stroke();
9645	
9646	  // --- 4. Animated car silhouette ---
9647	  const elapsed = time - _menuEntranceTime;
9648	  const carSlideT = Math.max(0, Math.min(1, (elapsed - MC.CAR_SLIDE_DELAY) / MC.CAR_SLIDE_DURATION));
9649	  const carEasedT = _easeOutCubic(carSlideT);
9650	  const carTargetX = W / 2;
9651	  const carStartX = W + 200;
9652	  const carX = carStartX + (carTargetX - carStartX) * carEasedT;
9653	  const carY = H * 0.80;
9654	  const carScale = 0.9 + 0.1 * carEasedT; // slight scale pop at end
9655	
9656	  // Road line behind car
9657	  ctx.strokeStyle = 'rgba(255, 255, 255, 0.06)';
9658	  ctx.lineWidth = 2;
9659	  ctx.beginPath();
9660	  ctx.moveTo(0, carY + 22 * carScale);
9661	  ctx.lineTo(W, carY + 22 * carScale);
9662	  ctx.stroke();
9663	
9664	  // Draw car with slight alpha fade during slide
9665	  ctx.globalAlpha = 0.5 + 0.5 * carEasedT;
9666	  _drawCarSilhouette(ctx, carX, carY, carScale);
9667	  ctx.globalAlpha = 1;
9668	
9669	  // Speed lines behind the car during entrance
9670	  if (carSlideT < 1 && carSlideT > 0.05) {
9671	    const lineAlpha = (1 - carSlideT) * 0.5;
9672	    ctx.strokeStyle = 'rgba(200, 210, 230, ' + lineAlpha + ')';
9673	    ctx.lineWidth = 1;
9674	    const lineCount = 8;
9675	    for (let i = 0; i < lineCount; i++) {
9676	      const lx = carX + 140 * carScale + Math.random() * 300;
9677	      const ly = carY - 20 * carScale + (Math.random() - 0.5) * 40 * carScale;
9678	      const ll = 30 + Math.random() * 80;
9679	      ctx.beginPath();
9680	      ctx.moveTo(lx, ly);
9681	      ctx.lineTo(lx + ll, ly);
9682	      ctx.stroke();
9683	    }
9684	  }
9685	
9686	  // --- 5. Blinking prompt ---
9687	  const promptY = H * 0.90;
9688	  const pulseAlpha = 0.5 + 0.5 * Math.sin(time * MC.PULSE_SPEED);
9689	  ctx.fillStyle = 'rgba(255, 255, 255, ' + (0.6 + pulseAlpha * 0.4) + ')';
9690	  ctx.font = MC.PROMPT_FONT;
9691	  ctx.textAlign = 'center';
9692	  ctx.textBaseline = 'middle';
9693	  ctx.shadowColor = 'rgba(255, 255, 255, ' + (pulseAlpha * 0.4) + ')';
9694	  ctx.shadowBlur = 8 + pulseAlpha * 6;
9695	  ctx.fillText('PRESS ENTER TO RACE', W / 2, promptY);
9696	  ctx.shadowBlur = 0;
9697	
9698	  // --- 6. Controls hint ---
9699	  const hintY = H * 0.945;
9700	  ctx.fillStyle = MC.HINT_COLOR;
9701	  ctx.font = MC.HINT_FONT;
9702	  ctx.textAlign = 'center';
9703	  ctx.textBaseline = 'middle';
9704	  ctx.fillText('↑↓←→ or WASD to drive | SHIFT for boost | ESC to pause', W / 2, hintY);
9705	
9706	  // --- 7. Version number ---
9707	  ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
9708	  ctx.font = MC.VERSION_FONT;
9709	  ctx.textAlign = 'right';
9710	  ctx.textBaseline = 'bottom';
9711	  ctx.fillText('v1.0', W - 16, H - 12);
9712	};
