9778	/* =====================================================================
9779	   R.renderCountdownScreen(number) — Countdown Numbers
9780	   Called each frame with the current number (3, 2, 1, or "GO!").
9781	   Scale animation with cubic ease-out.
9782	   ===================================================================== */
9783	
9784	R.renderCountdownScreen = function(number) {
9785	  const ctx = R.ctx;
9786	  const W = R.canvas.width;
9787	  const H = R.canvas.height;
9788	  const time = R.state.time;
9789	
9790	  // Detect count change
9791	  if (_lastCountNumber !== number) {
9792	    _lastCountNumber = number;
9793	    _countChangeTime = time;
9794	  }
9795	
9796	  // Compute scale with cubic ease-out
9797	  const elapsed = time - _countChangeTime;
9798	  const duration = MC.COUNTDOWN_DURATION;
9799	  const t = Math.min(elapsed / duration, 1);
9800	  const scale = 1 + (MC.COUNTDOWN_START_SCALE - 1) * Math.pow(1 - t, 3);
9801	  const alpha = number === 'GO!' ? 1 : 0.5 + 0.5 * Math.pow(1 - t, 2); // fade in as it shrinks
9802	
9803	  ctx.save();
9804	
9805	  // Semi-transparent backdrop
9806	  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
9807	  ctx.fillRect(0, 0, W, H);
9808	
9809	  // Text color: white for numbers, gold for GO!
9810	  const isGo = (number === 'GO!');
9811	  const textColor = isGo ? '#ffdd44' : '#ffffff';
9812	  const glowColor = isGo ? 'rgba(255, 200, 50, 0.5)' : 'rgba(255, 255, 255, 0.35)';
9813	
9814	  ctx.textAlign = 'center';
9815	  ctx.textBaseline = 'middle';
9816	  ctx.font = MC.COUNTDOWN_FONT;
9817	
9818	  // Apply scale transform around center
9819	  ctx.translate(W / 2, H * 0.42);
9820	  ctx.scale(scale, scale);
9821	  ctx.globalAlpha = alpha;
9822	
9823	  // Glow
9824	  ctx.shadowColor = glowColor;
9825	  ctx.shadowBlur = 18 * scale;
9826	  ctx.fillStyle = textColor;
9827	  ctx.fillText(String(number), 0, 0);
9828	
9829	  // Second pass: brighter core
9830	  ctx.shadowBlur = 0;
9831	  ctx.fillStyle = textColor;
9832	  ctx.fillText(String(number), 0, 0);
9833	
9834	  ctx.restore();
9835	};
