9841	R.renderFinishScreen = function() {
9842	  const ctx = R.ctx;
9843	  const W = R.canvas.width;
9844	  const H = R.canvas.height;
9845	
9846	  // --- 1. Dark semi-transparent background ---
9847	  ctx.fillStyle = 'rgba(0, 0, 0, ' + MC.OVERLAY_ALPHA + ')';
9848	  ctx.fillRect(0, 0, W, H);
9849	
9850	  // --- 2. "RACE COMPLETE!" title with golden gradient ---
9851	  const finishTitleY = H * 0.12;
