9853	    'RACE COMPLETE!',
9854	    W / 2,
9855	    finishTitleY,
9856	    MC.GOLD_TOP,
9857	    MC.GOLD_BOTTOM,
9858	    MC.FINISH_TITLE_FONT
9859	  );
9860	
9861	  // Add subtle glow behind title
9862	  ctx.save();
9863	  ctx.font = MC.FINISH_TITLE_FONT;
9864	  ctx.textAlign = 'center';
9865	  ctx.textBaseline = 'alphabetic';
9866	  ctx.shadowColor = 'rgba(255, 200, 50, 0.4)';
9867	  ctx.shadowBlur = 20;
9868	  ctx.fillStyle = 'rgba(0, 0, 0, 0)';
9869	  ctx.fillText('RACE COMPLETE!', W / 2, finishTitleY);
9870	  ctx.shadowBlur = 0;
9871	  ctx.restore();
9872	
9873	  // --- Gather race results ---
9874	  // Try R.raceResults first, otherwise build from R.cars.
9875	  /** @type {Array<{name:string, time:number, color:string, isPlayer:boolean}>} */
9876	  let results = [];
9877	  let playerName = 'You';
9878	  let playerIndex = -1;
9879	
9880	  if (R.raceResults && R.raceResults.length > 0) {
9881	    // Pre-computed results array
9882	    results = R.raceResults.map(function(r, i) {
9883	      return {
9884	        name: r.name || r.driver || ('Racer ' + (i + 1)),
9885	        time: r.time || r.raceTime || r.finishTime || 0,
9886	        color: r.color || '#888888',
9887	        isPlayer: r.isPlayer || false,
9888	      };
9889	    });
9890	    for (let i = 0; i < results.length; i++) {
9891	      if (results[i].isPlayer) { playerIndex = i; break; }
9892	    }
9893	  } else if (R.cars && R.cars.length > 0) {
9894	    // Build from car objects: sort by raceTime, then by laps descending for DNF
9895	    const cars = R.cars.slice();
9896	    cars.sort(function(a, b) {
9897	      // Finished cars first, sorted by time
9898	      if (a.finished && b.finished) return (a.raceTime || 0) - (b.raceTime || 0);
9899	      if (a.finished && !b.finished) return -1;
9900	      if (!a.finished && b.finished) return 1;
9901	      // Both unfinished: more laps = better position
9902	      const lapDiff = (b.lap || 0) - (a.lap || 0);
9903	      if (lapDiff !== 0) return lapDiff;
9904	      return (b.checkpointIdx || 0) - (a.checkpointIdx || 0);
9905	    });
9906	    results = cars.map(function(car, i) {
9907	      return {
9908	        name: car.name || car.driverName || (i === 0 ? 'You' : 'AI ' + i),
9909	        time: car.raceTime != null ? car.raceTime : null,
9910	        color: car.color || '#888888',
9911	        isPlayer: car.isPlayer || (i === 0),
9912	      };
9913	    });
9914	    for (let i = 0; i < results.length; i++) {
9915	      if (results[i].isPlayer) { playerIndex = i; break; }
9916	    }
9917	  }
9918	
9919	  // If still no results, show a placeholder
9920	  if (results.length === 0) {
9921	    results = [{ name: 'You', time: R.state.time || 0, color: '#ff6644', isPlayer: true }];
9922	    playerIndex = 0;
9923	  }
9924	
9925	  // --- 3. Results table ---
9926	  const tableTop = H * 0.25;
9927	  const headerY = tableTop;
9928	  const rowH = 36;
9929	  const colPad = 16;
9930	  const tableW = Math.min(W * 0.72, 600);
9931	  const tableX = (W - tableW) / 2;
9932	
9933	  // Panel behind table
9934	  const panelPad = 20;
9935	  const panelH = headerY + (results.length + 1) * rowH + panelPad * 2 - tableTop + 10;
9936	  R.drawPanel(tableX - panelPad, tableTop - panelPad, tableW + panelPad * 2, panelH, 0.85);
9937	
9938	  // Column layout
9939	  const posColX = tableX + 30;
9940	  const nameColX = tableX + 100;
9941	  const timeColX = tableX + tableW - 40;
9942	
9943	  // --- Header row ---
9944	  ctx.fillStyle = '#8899aa';
9945	  ctx.font = 'bold ' + MC.RESULTS_HEADER_SIZE + 'px ' + MC.RESULTS_FONT;
9946	  ctx.textBaseline = 'middle';
9947	
9948	  ctx.textAlign = 'left';
9949	  ctx.fillText('POS', posColX, headerY);
9950	  ctx.fillText('DRIVER', nameColX, headerY);
9951	  ctx.textAlign = 'right';
9952	  ctx.fillText('TIME', timeColX, headerY);
9953	
9954	  // Header underline
9955	  const headerLineY = headerY + rowH * 0.55;
9956	  ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
9957	  ctx.lineWidth = 1;
9958	  ctx.beginPath();
9959	  ctx.moveTo(tableX, headerLineY);
9960	  ctx.lineTo(tableX + tableW, headerLineY);
9961	  ctx.stroke();
9962	
9963	  // --- Result rows ---
9964	  results.forEach(function(result, i) {
9965	    const rowY = headerY + rowH + i * rowH;
9966	    const isPlayer = result.isPlayer;
9967	
9968	    // Row highlight for player
9969	    if (isPlayer) {
9970	      ctx.fillStyle = 'rgba(255, 255, 255, 0.08)';
