9976	
9977	    // Position
9978	    ctx.fillStyle = i === 0 ? MC.GOLD_TOP : (i === 1 ? '#cccccc' : (i === 2 ? '#cc9966' : '#889999'));
9979	    ctx.font = 'bold ' + MC.RESULTS_ROW_SIZE + 'px ' + MC.RESULTS_FONT;
9980	    ctx.textAlign = 'left';
9981	    ctx.fillText(_ordinal(i + 1), posColX, rowY);
9982	
9983	    // Driver name
9984	    ctx.fillStyle = isPlayer ? (result.color || '#ffffff') : '#cccccc';
9985	    ctx.font = (isPlayer ? 'bold ' : '') + MC.RESULTS_ROW_SIZE + 'px ' + MC.RESULTS_FONT;
9986	    ctx.fillText(result.name, nameColX, rowY);
9987	
9988	    // Time
9989	    const timeStr = (result.time != null) ? _formatRaceTime(result.time) : 'DNF';
9990	    ctx.fillStyle = (result.time != null) ? '#dddddd' : '#ff6666';
9991	    ctx.font = MC.RESULTS_ROW_SIZE + 'px ' + MC.RESULTS_FONT;
9992	    ctx.textAlign = 'right';
9993	    ctx.fillText(timeStr, timeColX, rowY);
9994	  });
9995	
9996	  // --- 4. Victory message if player is 1st ---
9997	  if (playerIndex === 0) {
9998	    const victoryY = tableTop + panelH + 16;
9999	    ctx.fillStyle = MC.GOLD_TOP;
10000	    ctx.font = 'bold 32px "Segoe UI","Arial Black",sans-serif';
10001	    ctx.textAlign = 'center';
10002	    ctx.textBaseline = 'top';
10003	    ctx.shadowColor = 'rgba(255, 200, 50, 0.5)';
