10018	  const promptY1 = H * 0.90;
10019	  const promptY2 = H * 0.94;
10020	
10021	  ctx.fillStyle = '#ffffff';
10022	  ctx.font = MC.PROMPT_FONT;
10023	  ctx.textAlign = 'center';
