2766	/* ==========================================================================
2767	   R.playerCollide(obstacleX, obstacleY, obstacleRadius)
2768	   Called by collision system. Bounces player and spawns visual marker.
2769	   Returns true if collision was processed.
2770	   ========================================================================== */
2771	R.playerCollide = function playerCollide(ox, oy, oRadius) {
2772	  const p = R.player;
2773	  if (!p) return false;
2774	
2775	  spawnBounceMarker(p.x, p.y);
2776	
2777	  // Push player away from obstacle center
2778	  const dx = p.x - ox;
2779	  const dy = p.y - oy;
2780	  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
2781	  const pushDist = (oRadius || 30) + R.CONFIG.CAR_WIDTH * 0.6;
2782	  p.x = ox + (dx / dist) * pushDist;
2783	  p.y = oy + (dy / dist) * pushDist;
2784	
2785	  // Kill speed
2786	  p.speed *= 0.4;
2787	  p.driftFactor *= 0.5;
2788	
2789	  return true;
2790	};
