2808	R.renderPlayerCar = function renderPlayerCar() {
2809	  const p = R.player;
2810	  if (!p) return;
2811	
2812	  const cfg = R.CONFIG;
2813	  const ctx = R.ctx;
2814	  const cam = R.camera || { x: 0, y: 0, zoom: 1 };
2815	  const zoom = cam.zoom;
2816	
2817	  // Convert world position to screen
2818	  const screen = R.worldToScreen(p.x, p.y);
2819	  const sx = screen.sx;
2820	  const sy = screen.sy;
2821	
2822	  // Culling: skip if far off screen
2823	  const W = (R.canvas && R.canvas.width)  || 1280;
2824	  const H = (R.canvas && R.canvas.height) || 720;
2825	  const margin = 200;
2826	  if (sx < -margin || sx > W + margin || sy < -margin || sy > H + margin) return;
2827	
2828	  const carLen   = cfg.CAR_LENGTH   * zoom;
2829	  const carHalfW = cfg.CAR_WIDTH    * 0.5 * zoom;
2830	  const wheelLen = cfg.WHEEL_LENGTH * zoom;
2831	  const wheelW   = cfg.WHEEL_WIDTH  * zoom;
2832	  const wheelBase = cfg.WHEELBASE   * zoom;
2833	
2834	  ctx.save();
2835	  ctx.translate(sx, sy);
2836	  ctx.rotate(p.angle);
2837	
2838	  // ── 1. SHADOW ────────────────────────────────────────────────────
2839	  const shadowOx = cfg.SHADOW_OFFSET_X * zoom;
2840	  const shadowOy = cfg.SHADOW_OFFSET_Y * zoom;
2841	  ctx.save();
2842	  ctx.translate(shadowOx, shadowOy);
2843	  ctx.fillStyle = `rgba(0, 0, 0, ${cfg.SHADOW_ALPHA})`;
2844	  ctx.beginPath();
2845	  ctx.ellipse(0, 0, carLen * 0.52, carHalfW * 1.15, 0, 0, Math.PI * 2);
2846	  ctx.fill();
2847	  ctx.restore();
2848	
2849	  // ── 2. CAR BODY ──────────────────────────────────────────────────
2850	  // Main body — rounded rectangle
2851	  const bodyFront  =  carLen * 0.5;
2852	  const bodyRear   = -carLen * 0.5;
2853	  const bodyRadius =  carHalfW * 0.55;
2854	
2855	  ctx.fillStyle = p.color;
2856	  ctx.strokeStyle = p.accentColor;
2857	  ctx.lineWidth = 2 * zoom;
2858	  ctx.beginPath();
2859	  roundedRect(ctx, bodyRear, -carHalfW, carLen, carHalfW * 2, bodyRadius);
2860	  ctx.fill();
2861	  ctx.stroke();
2862	
2863	  // Body panel lines — hood cut
2864	  ctx.strokeStyle = 'rgba(255,255,255,0.12)';
2865	  ctx.lineWidth = 1 * zoom;
2866	  ctx.beginPath();
2867	  ctx.moveTo(bodyFront * 0.65, -carHalfW * 0.85);
2868	  ctx.lineTo(bodyFront * 0.65,  carHalfW * 0.85);
2869	  ctx.stroke();
2870	
2871	  // ── 3. WINDSHIELD ────────────────────────────────────────────────
2872	  const wsFront =  carLen * 0.5  - carLen * 0.06;
2873	  const wsRear  =  carLen * 0.5  - carLen * cfg.WINDSHIELD_RATIO;
2874	  ctx.fillStyle = 'rgba(20, 40, 60, 0.7)';
2875	  ctx.beginPath();
2876	  ctx.moveTo(wsFront, -carHalfW * 0.84);
2877	  ctx.lineTo(wsRear,  -carHalfW * 0.88);
2878	  ctx.lineTo(wsRear,   carHalfW * 0.88);
2879	  ctx.lineTo(wsFront,  carHalfW * 0.84);
2880	  ctx.closePath();
2881	  ctx.fill();
2882	
2883	  // Windshield highlight
2884	  ctx.fillStyle = 'rgba(180, 210, 255, 0.25)';
2885	  ctx.beginPath();
2886	  ctx.moveTo(wsFront * 0.85 + wsRear * 0.15, -carHalfW * 0.35);
2887	  ctx.lineTo(wsRear * 0.7 + wsFront * 0.3,  -carHalfW * 0.55);
2888	  ctx.lineTo(wsRear * 0.7 + wsFront * 0.3,  -carHalfW * 0.15);
2889	  ctx.closePath();
2890	  ctx.fill();
2891	
2892	  // ── 4. REAR WINDOW ───────────────────────────────────────────────
2893	  const rwFront = -carLen * 0.5 + carLen * cfg.REAR_WINDOW_RATIO;
2894	  const rwRear  = -carLen * 0.5 + carLen * 0.05;
2895	  ctx.fillStyle = 'rgba(20, 35, 55, 0.6)';
2896	  ctx.beginPath();
2897	  ctx.moveTo(rwRear,  -carHalfW * 0.82);
2898	  ctx.lineTo(rwFront, -carHalfW * 0.85);
2899	  ctx.lineTo(rwFront,  carHalfW * 0.85);
2900	  ctx.lineTo(rwRear,   carHalfW * 0.82);
2901	  ctx.closePath();
2902	  ctx.fill();
2903	
2904	  // ── 5. RACING STRIPE ─────────────────────────────────────────────
2905	  const stripeW = cfg.STRIPE_WIDTH * 0.5 * zoom;
2906	  ctx.fillStyle = p.accentColor;
2907	  ctx.fillRect(-carLen * 0.44, -stripeW, carLen * 0.88, stripeW * 2);
2908	
2909	  // Thin pinstripe either side of center
2910	  ctx.fillStyle = 'rgba(255,255,255,0.2)';
2911	  const pinY = stripeW * 2.5;
2912	  ctx.fillRect(-carLen * 0.42, -pinY, carLen * 0.84, 0.8 * zoom);
2913	  ctx.fillRect(-carLen * 0.42,  pinY, carLen * 0.84, 0.8 * zoom);
2914	
2915	  // ── 6. HEADLIGHTS ────────────────────────────────────────────────
2916	  ctx.fillStyle = '#ffffcc';
2917	  ctx.shadowColor = 'rgba(255, 255, 180, 0.6)';
2918	  ctx.shadowBlur = 4 * zoom;
2919	  ctx.fillRect(bodyFront - 2 * zoom, -carHalfW * 0.72, 5 * zoom, 4 * zoom);
2920	  ctx.fillRect(bodyFront - 2 * zoom,  carHalfW * 0.72 - 4 * zoom, 5 * zoom, 4 * zoom);
2921	  ctx.shadowColor = 'transparent';
2922	  ctx.shadowBlur = 0;
2923	
2924	  // ── 7. TAILLIGHTS ────────────────────────────────────────────────
2925	  // Glow brighter when braking
2926	  const brakeGlow = (R.input && R.input.brake) ? 1 : 0.4;
2927	  ctx.fillStyle = `rgba(255, 30, 30, ${0.6 + brakeGlow * 0.4})`;
2928	  ctx.shadowColor = `rgba(255, 0, 0, ${0.7 * brakeGlow})`;
2929	  ctx.shadowBlur = 6 * zoom * brakeGlow;
2930	  ctx.fillRect(bodyRear + 0.5 * zoom, -carHalfW * 0.72, 4.5 * zoom, 3.5 * zoom);
2931	  ctx.fillRect(bodyRear + 0.5 * zoom,  carHalfW * 0.72 - 3.5 * zoom, 4.5 * zoom, 3.5 * zoom);
2932	  ctx.shadowColor = 'transparent';
2933	  ctx.shadowBlur = 0;
2934	
2935	  // ── 8. WHEELS ────────────────────────────────────────────────────
2936	  // Steering rotation for front wheels only
2937	  const steerVis = p.steerAngle * 0.65; // visual steer reduced for readability
2938	
2939	  // Wheel positions (local coords)
2940	  const wheelPositions = [
2941	    { x:  wheelBase * 0.5,  y: -carHalfW - wheelW * 0.2, steer: steerVis, tag: 'FL' },
2942	    { x:  wheelBase * 0.5,  y:  carHalfW + wheelW * 0.2, steer: steerVis, tag: 'FR' },
2943	    { x: -wheelBase * 0.5,  y: -carHalfW - wheelW * 0.2, steer: 0,        tag: 'RL' },
2944	    { x: -wheelBase * 0.5,  y:  carHalfW + wheelW * 0.2, steer: 0,        tag: 'RR' },
2945	  ];
2946	
2947	  for (const wp of wheelPositions) {
2948	    ctx.save();
2949	    ctx.translate(wp.x, wp.y);
2950	    ctx.rotate(wp.steer);
2951	
2952	    // Tire rubber
2953	    ctx.fillStyle = '#1a1a1a';
2954	    ctx.fillRect(-wheelLen * 0.5, -wheelW * 0.5, wheelLen, wheelW);
2955	
