792	  var smooth = R.CONFIG.CAMERA_SMOOTH;
793	  var offY   = R.CONFIG.CAMERA_OFFSET_Y;
794	
795	  // Frame-rate-independent lerp factor
796	  var t = 1 - Math.pow(1 - smooth, dt * 60);
