6545	  // ──────────────────────────────────────────────
6546	  // Helper utilities (pure functions, no allocations)
6547	  // ──────────────────────────────────────────────
6548	
6549	  /**
6550	   * Return a random float in [min, max).
6551	   * @param {number} min
6552	   * @param {number} max
6553	   * @returns {number}
6554	   */
6555	  function randRange(min, max) {
6556	    return min + Math.random() * (max - min);
6557	  }
6558	
6559	  /**
6560	   * Return a random integer in [min, max] inclusive.
6561	   * @param {number} min
6562	   * @param {number} max
6563	   * @returns {number}
6564	   */
6565	  function randInt(min, max) {
6566	    return Math.floor(randRange(min, max + 1));
6567	  }
6568	
6569	  /**
6570	   * Pick a random element from an array (used only at spawn time, not in hot render path).
6571	   * @param {Array} arr
6572	   * @returns {*}
6573	   */
6574	  function randPick(arr) {
6575	    return arr[randInt(0, arr.length - 1)];
6576	  }
6577	
6578	  /**
6579	   * Clamp a value between min and max.
6580	   * @param {number} val
6581	   * @param {number} min
6582	   * @param {number} max
6583	   * @returns {number}
6584	   */
6585	  function clamp(val, min, max) {
6586	    return val < min ? min : (val > max ? max : val);
6587	  }
6588	
6589	  /**
6590	   * Linear interpolation between two hex-like colors by decomposing RGB channels.
6591	   * Returns a CSS rgb() string for simplicity.
6592	   * @param {string} c1 - hex color like '#FF8800'
6593	   * @param {string} c2 - hex color like '#FF0000'
6594	   * @param {number} t - blend factor 0..1
6595	   * @returns {string} rgb() string
6596	   */
6597	  function lerpColor(c1, c2, t) {
6598	    const r1 = parseInt(c1.slice(1, 3), 16);
6599	    const g1 = parseInt(c1.slice(3, 5), 16);
6600	    const b1 = parseInt(c1.slice(5, 7), 16);
6601	    const r2 = parseInt(c2.slice(1, 3), 16);
6602	    const g2 = parseInt(c2.slice(3, 5), 16);
6603	    const b2 = parseInt(c2.slice(5, 7), 16);
6604	    const r = Math.round(r1 + (r2 - r1) * t);
6605	    const g = Math.round(g1 + (g2 - g1) * t);
6606	    const b = Math.round(b1 + (b2 - b1) * t);
6607	    return 'rgb(' + r + ',' + g + ',' + b + ')';
6608	  }
