6610	  /**
6611	   * Return a spark color based on life ratio (1.0 = newborn → 0.0 = dying).
6612	   * Early life: bright yellow-white; mid: orange; late: red; end: dark red.
6613	   * @param {number} t - life ratio 0..1
6614	   * @returns {string} hex color
6615	   */
6616	  function sparkColorByLife(t) {
6617	    const idx = Math.floor((1 - t) * (SPARK_COLORS.length - 1));
6618	    return SPARK_COLORS[clamp(idx, 0, SPARK_COLORS.length - 1)];
6619	  }
6620	
6621	  /**
6622	   * Return a smoke color based on life ratio (newborn light gray → dying darker).
6623	   * @param {number} t - life ratio 0..1
6624	   * @returns {string} hex color
6625	   */
6626	  function smokeColorByLife(t) {
6627	    const idx = Math.floor(t * (SMOKE_COLORS.length - 1));
6628	    return SMOKE_COLORS[clamp(idx, 0, SMOKE_COLORS.length - 1)];
6629	  }
