6635	  /** @type {number} Next spawn slot in the pool (cyclic). */
6636	  let _nextSpawnIndex = 0;
6637	
6638	  /**
6639	   * Create a dead particle template.
6640	   * @returns {Object}
6641	   */
6642	  function createDeadParticle() {
6643	    return {
6644	      x: 0,
6645	      y: 0,
6646	      vx: 0,
6647	      vy: 0,
6648	      life: 0,
6649	      maxLife: 0,
6650	      size: 0,
6651	      color: '#000',
6652	      alpha: 0,
6653	      type: 'spark'   // 'spark' | 'smoke' | 'dust' | 'debris'
6654	    };
6655	  }
