6657	  /**
6658	   * Initialize the particle pool.
6659	   * Pre-allocate R.particles with MAX_PARTICLES dead particles.
6660	   * Safe to call multiple times — clears and rebuilds the pool.
6661	   */
6662	  R.initEffects = function() {
6663	    const max = R.CONFIG.MAX_PARTICLES;
6664	    R.particles = new Array(max);
6665	    for (let i = 0; i < max; i++) {
6666	      R.particles[i] = createDeadParticle();
6667	    }
6668	    _nextSpawnIndex = 0;
6669	    R._shakeIntensity = 0;
6670	    R._shakeDuration = 0;
6671	    R._shakeTimer = 0;
6672	  };
6673	
6674	  /**
6675	   * Activate a dead particle from the pool and configure it.
6676	   * If no dead particle is available, recycle the oldest one (cyclic overwrite).
6677	   *
6678	   * @param {number} x - world/screen X position
6679	   * @param {number} y - world/screen Y position
6680	   * @param {Object} config
6681	   * @param {number} [config.vx] - horizontal velocity; random if omitted
6682	   * @param {number} [config.vy] - vertical velocity; random if omitted
6683	   * @param {number} [config.vxRange] - if vx omitted, random range [-vxRange, vxRange]
6684	   * @param {number} [config.vyRange] - if vy omitted, random range [-vyRange, vyRange]
6685	   * @param {number} config.life - particle lifetime in frames
6686	   * @param {number} config.size - particle size in px
6687	   * @param {string} config.color - fill color (hex or rgb)
6688	   * @param {string} [config.type='spark'] - particle type
6689	   * @param {number} [config.alpha=1] - starting alpha
6690	   * @returns {Object|null} the activated particle, or null if pool is empty (should not happen)
6691	   */
6692	  R.spawnParticle = function(x, y, config) {
6693	    if (!R.particles || R.particles.length === 0) return null;
6694	
6695	    const max = R.particles.length;
6696	    let p = null;
6697	
6698	    // Strategy 1: find the first dead particle starting from the current
6699	    // write-pointer position (avoids always scanning from index 0).
6700	    for (let attempt = 0; attempt < max; attempt++) {
6701	      const idx = (_nextSpawnIndex + attempt) % max;
6702	      if (R.particles[idx].life <= 0) {
6703	        p = R.particles[idx];
6704	        _nextSpawnIndex = (idx + 1) % max;
6705	        break;
6706	      }
6707	    }
6708	
6709	    // Strategy 2: all particles are alive — recycle the oldest (cyclic write pointer).
6710	    if (!p) {
6711	      p = R.particles[_nextSpawnIndex];
6712	      _nextSpawnIndex = (_nextSpawnIndex + 1) % max;
6713	    }
6714	
6715	    // Configure particle
6716	    p.x = x;
6717	    p.y = y;
6718	    p.vx = config.vx !== undefined ? config.vx : randRange(-(config.vxRange || 3), config.vxRange || 3);
6719	    p.vy = config.vy !== undefined ? config.vy : randRange(-(config.vyRange || 3), config.vyRange || 3);
6720	    p.life = config.life || 30;
6721	    p.maxLife = config.life || 30;
6722	    p.size = config.size || 3;
6723	    p.color = config.color || '#FFFFFF';
6724	    p.alpha = config.alpha !== undefined ? config.alpha : 1.0;
6725	    p.type = config.type || 'spark';
6726	
6727	    return p;
6728	  };
