6809	  /**
6810	   * Spawn tire smoke during drifting from both rear wheel positions.
6811	   * Two plumes from rear wheel positions offset from car center.
6812	   * intensity affects spawn rate and particle count (~1-6 particles per plume per call).
6813	   *
6814	   * @param {number} carX - car center X (world)
6815	   * @param {number} carY - car center Y (world)
6816	   * @param {number} carAngle - car heading angle in radians
6817	   * @param {number} intensity - 0..1 drift intensity (0 = no drift, 1 = full lock)
6818	   */
6819	  R.spawnDriftSmoke = function(carX, carY, carAngle, intensity) {
6820	    if (intensity <= 0.02) return;   // negligible — skip
6821	
6822	    // Rear wheel positions relative to car center
6823	    const rearOffset = 35;   // px behind center
6824	    const wheelSpan = 22;    // px left/right of center
6825	
6826	    const cosA = Math.cos(carAngle);
6827	    const sinA = Math.sin(carAngle);
6828	
6829	    // Rear-left wheel world position
6830	    const rlX = carX - rearOffset * cosA - wheelSpan * sinA;
6831	    const rlY = carY - rearOffset * sinA + wheelSpan * cosA;
6832	
6833	    // Rear-right wheel world position
6834	    const rrX = carX - rearOffset * cosA + wheelSpan * sinA;
6835	    const rrY = carY - rearOffset * sinA - wheelSpan * cosA;
6836	
6837	    // Particle count per plume scales with intensity
6838	    const baseCount = Math.floor(intensity * 6) + 1;
6839	
6840	    for (let plume = 0; plume < 2; plume++) {
6841	      const px = plume === 0 ? rlX : rrX;
6842	      const py = plume === 0 ? rlY : rrY;
6843	      const count = baseCount + randInt(0, 2);
6844	
6845	      for (let i = 0; i < count; i++) {
6846	        const life = randInt(30, 60);
6847	        const size = randRange(4, 10);
6848	
6849	        // Drift smoke billows outward from the drift direction
6850	        const spreadAngle = carAngle + Math.PI / 2 + randRange(-0.6, 0.6);
6851	        const spreadSpeed = randRange(0.5, 2.0) * intensity;
6852	
6853	        R.spawnParticle(px + randRange(-4, 4), py + randRange(-4, 4), {
6854	          vx: Math.cos(spreadAngle) * spreadSpeed,
6855	          vy: Math.sin(spreadAngle) * spreadSpeed - randRange(0.3, 1.0),   // slight upward
6856	          life: life,
6857	          size: size,
6858	          color: randPick(DRIFT_SMOKE_COLORS),
6859	          type: 'smoke',
6860	          alpha: randRange(0.3, 0.55) * intensity
6861	        });
6862	      }
6863	    }
6864	  };
