6895	  // ──────────────────────────────────────────────
6896	  // Particle update
6897	  // ──────────────────────────────────────────────
6898	
6899	  /**
6900	   * Update all alive particles.
6901	   * Called each frame from the game loop.
6902	   *
6903	   * Steps:
6904	   *  1. Decrement life by dt * 60 (normalize to ~60fps frame ticks)
6905	   *  2. Update position: x += vx * dt * 60, y += vy * dt * 60
6906	   *  3. Apply gravity to smoke / debris types: vy -= gravity
6907	   *  4. Fade alpha based on life/maxLife ratio
6908	   *  5. Mark dead if life <= 0
6909	   *
6910	   * @param {number} dt - delta time in seconds
6911	   */
6912	  R.updateEffects = function(dt) {
6913	    if (!R.particles || R.particles.length === 0) return;
6914	
6915	    const frameScale = dt * 60;   // normalize to 60fps equivalent
6916	    const gravity = R.CONFIG.PARTICLE_GRAVITY;
6917	    const particles = R.particles;
6918	    const len = particles.length;
6919	
6920	    for (let i = 0; i < len; i++) {
6921	      const p = particles[i];
6922	      if (p.life <= 0) continue;   // dead particle, skip
6923	
6924	      // 1. Decrement life
6925	      p.life -= frameScale * 1;    // life measured in frame-ticks
6926	
6927	      // 2. Update position
6928	      p.x += p.vx * frameScale;
6929	      p.y += p.vy * frameScale;
6930	
6931	      // 3. Apply gravity for affected types
6932	      if (p.type === 'smoke' || p.type === 'debris') {
6933	        p.vy += gravity * frameScale;
6934	      }
6935	
6936	      // 4. Fade alpha
6937	      const lifeRatio = p.life / p.maxLife;
6938	      if (p.type === 'smoke') {
6939	        // Smoke fades out in the last 40% of its life
6940	        p.alpha = lifeRatio > 0.4 ? p.alpha : (p.alpha * (lifeRatio / 0.4));
6941	      } else if (p.type === 'dust') {
6942	        // Dust fades smoothly
6943	        p.alpha = lifeRatio * 0.7;
6944	      } else {
6945	        // Sparks / debris: hold alpha then fade sharply at end
6946	        p.alpha = lifeRatio > 0.3 ? 1.0 : lifeRatio / 0.3;
6947	      }
6948	
6949	      // 5. Mark dead
6950	      if (p.life <= 0) {
6951	        p.life = 0;
6952	        p.alpha = 0;
6953	      }
6954	    }
6955	
6956	    // Update screen shake
6957	    R.updateScreenShake(dt);
6958	  };
6959	
6960	  // ──────────────────────────────────────────────
6961	  // Particle rendering
6962	  // ──────────────────────────────────────────────
6963	
6964	  /**
6965	   * Render all alive particles.
6966	   * Called each frame from the game loop.
6967	   * For each alive particle:
6968	   *   - Set ctx.globalAlpha = particle.alpha
6969	   *   - Set ctx.fillStyle based on particle type and life ratio
6970	   *   - Draw as small circle (spark, smoke, dust) or square (debris)
6971	   *   - Reset globalAlpha to 1.0
6972	   */
6973	  R.renderEffects = function() {
6974	    if (!R.particles || R.particles.length === 0) return;
6975	
6976	    const ctx = R.ctx;
6977	    const particles = R.particles;
6978	    const len = particles.length;
6979	    let aliveCount = 0;
6980	
6981	    ctx.save();
6982	
6983	    for (let i = 0; i < len; i++) {
6984	      const p = particles[i];
6985	      if (p.life <= 0 || p.alpha <= 0.005) continue;   // skip dead or invisible
6986	
6987	      aliveCount++;
6988	
6989	      const lifeRatio = clamp(p.life / p.maxLife, 0, 1);
6990	
6991	      // Determine color based on particle type
6992	      let color;
6993	      switch (p.type) {
6994	        case 'spark':
6995	          color = sparkColorByLife(lifeRatio);
6996	          break;
6997	        case 'smoke':
6998	          color = smokeColorByLife(lifeRatio);
6999	          break;
7000	        case 'dust':
7001	          color = p.color;    // dust uses its assigned color, just fades alpha
7002	          break;
7003	        case 'debris':
7004	          color = p.color;
7005	          break;
7006	        default:
7007	          color = p.color;
7008	      }
7009	
7010	      ctx.globalAlpha = clamp(p.alpha, 0, 1);
7011	      ctx.fillStyle = color;
7012	
7013	      const halfSize = p.size / 2;
7014	
7015	      switch (p.type) {
7016	        case 'spark':
7017	          // Small bright circle, sometimes with a glow
7018	          ctx.beginPath();
7019	          ctx.arc(p.x, p.y, halfSize, 0, Math.PI * 2);
7020	          ctx.fill();
7021	          // Tiny glow for bright sparks
7022	          if (lifeRatio > 0.5 && p.size >= 3) {
7023	            ctx.globalAlpha = clamp(p.alpha * 0.35, 0, 1);
7024	            ctx.beginPath();
7025	            ctx.arc(p.x, p.y, halfSize * 2, 0, Math.PI * 2);
7026	            ctx.fill();
7027	          }
7028	          break;
7029	
7030	        case 'smoke':
7031	          // Soft round puff
7032	          ctx.beginPath();
7033	          ctx.arc(p.x, p.y, halfSize, 0, Math.PI * 2);
7034	          ctx.fill();
7035	          break;
7036	
7037	        case 'dust':
7038	          // Small irregular — use a filled circle, optionally a little scatter
7039	          ctx.beginPath();
7040	          ctx.arc(p.x, p.y, halfSize, 0, Math.PI * 2);
7041	          ctx.fill();
7042	          break;
7043	
7044	        case 'debris':
7045	          // Small square / rectangle oriented randomly
7046	          ctx.fillRect(p.x - halfSize, p.y - halfSize * 0.6, p.size, p.size * 0.6);
7047	          break;
7048	
7049	        default:
7050	          ctx.beginPath();
7051	          ctx.arc(p.x, p.y, halfSize, 0, Math.PI * 2);
7052	          ctx.fill();
7053	      }
7054	    }
7055	
7056	    ctx.restore();
7057	    // Always reset globalAlpha
7058	    ctx.globalAlpha = 1.0;
7059	
7060	    return aliveCount;
7061	  };
