7063	  // ──────────────────────────────────────────────
7064	  // Screen shake
7065	  // ──────────────────────────────────────────────
7066	
7067	  /**
7068	   * Trigger a screen shake effect.
7069	   *
7070	   * @param {number} intensity - max pixel offset (e.g. 4 = up to 4px shake)
7071	   * @param {number} [duration=15] - shake duration in frames (~0.25s at 60fps)
7072	   */
7073	  R.triggerScreenShake = function(intensity, duration) {
7074	    if (!intensity || intensity <= 0) return;
7075	
7076	    const dur = duration || 15;
7077	
7078	    // If already shaking with higher intensity, don't downgrade
7079	    if (R._shakeTimer > 0 && R._shakeIntensity > intensity) {
7080	      // Keep the existing stronger shake
7081	      return;
7082	    }
7083	
7084	    R._shakeIntensity = clamp(intensity, 0, R.CONFIG.SHAKE_MAX_OFFSET);
7085	    R._shakeDuration = dur;
7086	    R._shakeTimer = dur;
7087	  };
7088	
7089	  /**
